package com.cooldownoverlays;

/**
 * Estimates the shared combat-boost decay phase from observed natural decreases.
 * Preserve timing follows RuneLite's BoostsPlugin. Call once per game tick, after
 * reporting that tick's observed decay, so prayer changes update qualification.
 */
final class BoostDecayClock
{
	private int lastDecayTick = -1;
	private int expectedDecayTick = -1;
	private boolean preserveBeenActive;

	void clear()
	{
		lastDecayTick = -1;
		expectedDecayTick = -1;
		preserveBeenActive = false;
	}

	void observeDecay(int tick)
	{
		// Several boosted skills may decrease in the same server batch.
		if (tick <= lastDecayTick)
		{
			return;
		}
		lastDecayTick = tick;
		expectedDecayTick = tick + 100;
		preserveBeenActive = false;
	}

	int ticksToNextDecay(int tick, boolean preserveActive)
	{
		if (lastDecayTick == -1)
		{
			return -1;
		}
		int elapsed = tick - lastDecayTick;
		if (elapsed < 0 || tick >= expectedDecayTick)
		{
			// A missed decrease can mean protected stats or an incorrect observation.
			// Never roll an unconfirmed prediction into another decay cycle.
			clear();
			return -1;
		}

		int interval;
		if ((preserveActive && (elapsed < 75 || preserveBeenActive)) || elapsed > 125)
		{
			preserveBeenActive = true;
			interval = 150;
		}
		else
		{
			preserveBeenActive = false;
			interval = elapsed > 100 ? 125 : 100;
		}

		if (interval <= elapsed)
		{
			clear();
			return -1;
		}
		expectedDecayTick = lastDecayTick + interval;
		return interval - elapsed;
	}
}

package com.cooldownoverlays;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Predicate;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;

/** Ordinary combat boosts, whose remaining duration depends on the player's stat decay. */
enum BoostPotion
{
	ATTACK(CooldownOverlaysConfig::attackPotion, new Boost[]{Boost.ATTACK},
		ItemID._4DOSE1ATTACK, ItemID._3DOSE1ATTACK, ItemID._2DOSE1ATTACK, ItemID._1DOSE1ATTACK,
		ItemID.BRUTAL_2DOSE1ATTACK, ItemID.BRUTAL_1DOSE1ATTACK),
	STRENGTH(CooldownOverlaysConfig::strengthPotion, new Boost[]{Boost.STRENGTH},
		ItemID.STRENGTH4, ItemID._3DOSE1STRENGTH, ItemID._2DOSE1STRENGTH, ItemID._1DOSE1STRENGTH,
		ItemID.BRUTAL_2DOSE1STRENGTH, ItemID.BRUTAL_1DOSE1STRENGTH),
	DEFENCE(CooldownOverlaysConfig::defencePotion, new Boost[]{Boost.DEFENCE},
		ItemID._4DOSE1DEFENSE, ItemID._3DOSE1DEFENSE, ItemID._2DOSE1DEFENSE, ItemID._1DOSE1DEFENSE,
		ItemID.BRUTAL_2DOSE1DEFENSE, ItemID.BRUTAL_1DOSE1DEFENSE),
	SUPER_ATTACK(CooldownOverlaysConfig::superAttackPotion, new Boost[]{Boost.SUPER_ATTACK},
		ItemID._4DOSE2ATTACK, ItemID._3DOSE2ATTACK, ItemID._2DOSE2ATTACK, ItemID._1DOSE2ATTACK,
		ItemID.BRUTAL_2DOSE2ATTACK, ItemID.BRUTAL_1DOSE2ATTACK),
	SUPER_STRENGTH(CooldownOverlaysConfig::superStrengthPotion, new Boost[]{Boost.SUPER_STRENGTH},
		ItemID._4DOSE2STRENGTH, ItemID._3DOSE2STRENGTH, ItemID._2DOSE2STRENGTH, ItemID._1DOSE2STRENGTH,
		ItemID.BRUTAL_2DOSE2STRENGTH, ItemID.BRUTAL_1DOSE2STRENGTH),
	SUPER_DEFENCE(CooldownOverlaysConfig::superDefencePotion, new Boost[]{Boost.SUPER_DEFENCE},
		ItemID._4DOSE2DEFENSE, ItemID._3DOSE2DEFENSE, ItemID._2DOSE2DEFENSE, ItemID._1DOSE2DEFENSE,
		ItemID.BRUTAL_2DOSE2DEFENSE, ItemID.BRUTAL_1DOSE2DEFENSE),
	COMBAT(CooldownOverlaysConfig::combatPotion, new Boost[]{Boost.ATTACK, Boost.STRENGTH},
		ItemID._4DOSECOMBAT, ItemID._3DOSECOMBAT, ItemID._2DOSECOMBAT, ItemID._1DOSECOMBAT,
		ItemID.BRUTAL_2DOSECOMBAT, ItemID.BRUTAL_1DOSECOMBAT,
		ItemID._4DOSECOMBAT_DEADMAN_STARTER, ItemID._3DOSECOMBAT_DEADMAN_STARTER,
		ItemID._2DOSECOMBAT_DEADMAN_STARTER, ItemID._1DOSECOMBAT_DEADMAN_STARTER),
	SUPER_COMBAT(CooldownOverlaysConfig::superCombatPotion,
		new Boost[]{Boost.SUPER_ATTACK, Boost.SUPER_STRENGTH, Boost.SUPER_DEFENCE},
		ItemID._4DOSE2COMBAT, ItemID._3DOSE2COMBAT, ItemID._2DOSE2COMBAT, ItemID._1DOSE2COMBAT),
	RANGING(CooldownOverlaysConfig::rangingPotion, new Boost[]{Boost.RANGED},
		ItemID._4DOSERANGERSPOTION, ItemID._3DOSERANGERSPOTION,
		ItemID._2DOSERANGERSPOTION, ItemID._1DOSERANGERSPOTION,
		ItemID.BRUTAL_2DOSERANGERSPOTION, ItemID.BRUTAL_1DOSERANGERSPOTION,
		ItemID.BR_4DOSERANGERSPOTION, ItemID.BR_3DOSERANGERSPOTION,
		ItemID.BR_2DOSERANGERSPOTION, ItemID.BR_1DOSERANGERSPOTION),
	MAGIC(CooldownOverlaysConfig::magicPotion, new Boost[]{Boost.MAGIC},
		ItemID._4DOSE1MAGIC, ItemID._3DOSE1MAGIC, ItemID._2DOSE1MAGIC, ItemID._1DOSE1MAGIC,
		ItemID.BRUTAL_2DOSE1MAGIC, ItemID.BRUTAL_1DOSE1MAGIC),
	BASTION(CooldownOverlaysConfig::bastionPotion, new Boost[]{Boost.RANGED, Boost.SUPER_DEFENCE},
		ItemID._4DOSEBASTION, ItemID._3DOSEBASTION, ItemID._2DOSEBASTION, ItemID._1DOSEBASTION),
	BATTLEMAGE(CooldownOverlaysConfig::battlemagePotion, new Boost[]{Boost.MAGIC, Boost.SUPER_DEFENCE},
		ItemID._4DOSEBATTLEMAGE, ItemID._3DOSEBATTLEMAGE, ItemID._2DOSEBATTLEMAGE, ItemID._1DOSEBATTLEMAGE);

	private enum Boost
	{
		ATTACK(Skill.ATTACK, 10, 3),
		STRENGTH(Skill.STRENGTH, 10, 3),
		DEFENCE(Skill.DEFENCE, 10, 3),
		SUPER_ATTACK(Skill.ATTACK, 15, 5),
		SUPER_STRENGTH(Skill.STRENGTH, 15, 5),
		SUPER_DEFENCE(Skill.DEFENCE, 15, 5),
		RANGED(Skill.RANGED, 10, 4),
		MAGIC(Skill.MAGIC, 0, 4);

		private final Skill skill;
		private final int percentage;
		private final int flat;

		Boost(Skill skill, int percentage, int flat)
		{
			this.skill = skill;
			this.percentage = percentage;
			this.flat = flat;
		}
	}

	private static final Map<Integer, BoostPotion> POTIONS;

	static
	{
		Map<Integer, BoostPotion> potions = new HashMap<>();
		for (BoostPotion potion : values())
		{
			for (int itemId : potion.itemIds)
			{
				if (potions.put(itemId, potion) != null)
				{
					throw new IllegalStateException("Boost potion belongs to multiple families: " + itemId);
				}
			}
		}
		POTIONS = Collections.unmodifiableMap(potions);
	}

	private final Predicate<CooldownOverlaysConfig> enabled;
	private final Boost[] boosts;
	private final int[] itemIds;

	BoostPotion(Predicate<CooldownOverlaysConfig> enabled, Boost[] boosts, int... itemIds)
	{
		this.enabled = enabled;
		this.boosts = boosts;
		this.itemIds = itemIds;
	}

	static BoostPotion forItem(int itemId)
	{
		return POTIONS.get(itemId);
	}

	boolean isEnabled(CooldownOverlaysConfig config)
	{
		return enabled.test(config);
	}

	Skill[] getSkills()
	{
		Skill[] skills = new Skill[boosts.length];
		for (int i = 0; i < boosts.length; i++)
		{
			skills[i] = boosts[i].skill;
		}
		return skills;
	}

	/** The stat cap of a dose, using the same floor-and-add formulas as RuneLite's item stats. */
	int getBoostedLevel(Skill skill, int baseLevel)
	{
		for (Boost boost : boosts)
		{
			if (boost.skill == skill)
			{
				return baseLevel + baseLevel * boost.percentage / 100 + boost.flat;
			}
		}
		return baseLevel;
	}
}

package com.cooldownoverlays;

import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;

/** Estimates time to a useful re-dose from actual combat stats and their shared decay phase. */
@Singleton
final class BoostPotionTimers
{
	private static final Skill[] SKILLS = {
		Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.MAGIC
	};
	private final Map<BoostPotion, Cooldown> timers = new EnumMap<>(BoostPotion.class);
	private final Map<Skill, Integer> previousBase = new EnumMap<>(Skill.class);
	private final Map<Skill, Integer> previousBoosted = new EnumMap<>(Skill.class);
	private final Set<Skill> previousProtected = EnumSet.noneOf(Skill.class);
	private final BoostDecayClock decayClock = new BoostDecayClock();
	private final Map<Skill, Integer> previousThresholds = new EnumMap<>(Skill.class);
	private boolean previousPreserve;

	BoostPotionTimers()
	{
		for (BoostPotion potion : BoostPotion.values())
		{
			timers.put(potion, new Cooldown());
		}
	}

	void tick(Client client, CooldownOverlaysConfig config, long nowNanos)
	{
		Map<Skill, Integer> base = new EnumMap<>(Skill.class);
		Map<Skill, Integer> boosted = new EnumMap<>(Skill.class);
		Map<Skill, Integer> thresholds = new EnumMap<>(Skill.class);
		thresholds.put(Skill.ATTACK, config.attackThreshold());
		thresholds.put(Skill.STRENGTH, config.strengthThreshold());
		thresholds.put(Skill.DEFENCE, config.defenceThreshold());
		thresholds.put(Skill.RANGED, config.rangedThreshold());
		thresholds.put(Skill.MAGIC, config.magicThreshold());
		for (Skill skill : SKILLS)
		{
			base.put(skill, client.getRealSkillLevel(skill));
			boosted.put(skill, client.getBoostedSkillLevel(skill));
		}
		tick(client.getTickCount(), base, boosted, protectedSkills(client, base, boosted),
			client.getVarbitValue(VarbitID.PRAYER_PRESERVE) > 0, thresholds, nowNanos);
	}

	void tick(int tick, Map<Skill, Integer> base, Map<Skill, Integer> boosted,
		Set<Skill> protectedSkills, boolean preserve, Map<Skill, Integer> thresholds, long nowNanos)
	{
		int nextDecay = decayClock.ticksToNextDecay(tick, preserve);
		for (Skill skill : SKILLS)
		{
			int level = base.getOrDefault(skill, 0);
			int current = boosted.getOrDefault(skill, level);
			Integer previous = previousBoosted.get(skill);
			if (level > 0 && boosted.containsKey(skill)
				&& !protectedSkills.contains(skill) && !previousProtected.contains(skill)
				&& previous != null && previousBase.getOrDefault(skill, 0) == level
				&& previous > level && current >= level && current == previous - 1
				&& (nextDecay == -1 || nextDecay <= 2))
			{
				// Restrict later observations to the expected window, reducing false phase
				// changes from one-level enemy drains. The first observation is an estimate.
				decayClock.observeDecay(tick);
			}
		}
		nextDecay = decayClock.ticksToNextDecay(tick, preserve);
		for (BoostPotion potion : BoostPotion.values())
		{
			Cooldown timer = timers.get(potion);
			boolean eligible = false;
			boolean ready = false;
			boolean refreshed = !thresholds.equals(previousThresholds) || preserve != previousPreserve;
			int earliestTicks = Integer.MAX_VALUE;
			for (Skill skill : potion.getSkills())
			{
				int level = base.getOrDefault(skill, 0);
				int threshold = thresholds.getOrDefault(skill, 0);
				if (threshold <= 0 || level <= 0 || !boosted.containsKey(skill)
					|| protectedSkills.contains(skill))
				{
					continue;
				}
				int current = boosted.getOrDefault(skill, level);
				int cap = potion.getBoostedLevel(skill, level);
				boolean skillReady = current < threshold && current < cap;
				int targetLevel = Math.min(threshold - 1, cap - 1);
				// Natural decay stops at base. A lower target can only be crossed by a
				// stat drain, so show no invented countdown while waiting for one.
				if (!skillReady && targetLevel < level)
				{
					continue;
				}
				eligible = true;
				if (skillReady)
				{
					ready = true;
				}
				else if (nextDecay > 0)
				{
					int levelsToThreshold = current - targetLevel;
					int ticks = nextDecay + (levelsToThreshold - 1) * (preserve ? 150 : 100);
					earliestTicks = Math.min(earliestTicks, ticks);
				}
				refreshed |= current > previousBoosted.getOrDefault(skill, current)
					|| level != previousBase.getOrDefault(skill, level);
			}
			if (!eligible)
			{
				timer.clear();
			}
			else if (ready)
			{
				timer.setReady(nowNanos);
			}
			else if (earliestTicks == Integer.MAX_VALUE)
			{
				timer.startUnknown(nowNanos);
			}
			else
			{
				int total = refreshed ? earliestTicks : Math.max(earliestTicks, timer.getTotalTicks());
				timer.start(earliestTicks, total, nowNanos);
			}
		}
		previousBase.clear();
		previousBase.putAll(base);
		previousBoosted.clear();
		previousBoosted.putAll(boosted);
		previousProtected.clear();
		previousProtected.addAll(protectedSkills);
		previousThresholds.clear();
		previousThresholds.putAll(thresholds);
		previousPreserve = preserve;
	}

	Cooldown get(BoostPotion potion)
	{
		return timers.get(potion);
	}

	void clear()
	{
		for (Cooldown timer : timers.values())
		{
			timer.clear();
		}
		previousBase.clear();
		previousBoosted.clear();
		previousProtected.clear();
		decayClock.clear();
		previousThresholds.clear();
		previousPreserve = false;
	}

	private static Set<Skill> protectedSkills(Client client, Map<Skill, Integer> base, Map<Skill, Integer> boosted)
	{
		Set<Skill> protectedSkills = EnumSet.noneOf(Skill.class);
		if ((client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1
			&& client.getVarbitValue(VarbitID.RAIDS_OVERLOAD_TIMER) > 0)
			|| client.getVarbitValue(VarbitID.NZONE_OVERLOAD_POTION_EFFECTS) > 0
			|| client.getVarbitValue(VarbitID.DEADMAN_OVERLOAD_POTION_EFFECTS) > 0
			|| client.getVarbitValue(VarbitID.TOA_MIDRAIDLOOT_STATS_TIMER) > 0)
		{
			for (Skill skill : SKILLS)
			{
				protectedSkills.add(skill);
			}
			return protectedSkills;
		}
		protect(client, protectedSkills, VarbitID.DIVINEATTACK_POTION_TIME, Skill.ATTACK);
		protect(client, protectedSkills, VarbitID.DIVINESTRENGTH_POTION_TIME, Skill.STRENGTH);
		int divineDefence = client.getVarbitValue(VarbitID.DIVINEDEFENCE_POTION_TIME);
		int moonlight = client.getVarbitValue(VarbitID.MOONLIGHT_POTION_TIME);
		// Moonlight shares the divine Defence marker but allows natural stat decay.
		// A genuinely longer divine effect still protects Defence from decay.
		if (divineDefence > 0 && (moonlight <= 0 || divineDefence > moonlight + 1))
		{
			protectedSkills.add(Skill.DEFENCE);
		}
		protect(client, protectedSkills, VarbitID.DIVINERANGE_POTION_TIME, Skill.RANGED);
		protect(client, protectedSkills, VarbitID.DIVINEMAGIC_POTION_TIME, Skill.MAGIC);
		protect(client, protectedSkills, VarbitID.DIVINECOMBAT_POTION_TIME, Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE);
		protect(client, protectedSkills, VarbitID.DIVINEBASTION_POTION_TIME, Skill.RANGED, Skill.DEFENCE);
		protect(client, protectedSkills, VarbitID.DIVINEBATTLEMAGE_POTION_TIME, Skill.MAGIC, Skill.DEFENCE);
		// The shared heart counter cannot identify which heart was used. A heart-sized
		// Magic boost cannot usefully be topped up by an ordinary magic potion yet.
		if (client.getVarbitValue(VarbitID.IMBUED_HEART_TIMER) > 0
			&& boosted.get(Skill.MAGIC) > base.get(Skill.MAGIC) + 4)
		{
			protectedSkills.add(Skill.MAGIC);
		}
		return protectedSkills;
	}

	private static void protect(Client client, Set<Skill> skills, int varbit, Skill... affected)
	{
		if (client.getVarbitValue(varbit) > 0)
		{
			for (Skill skill : affected)
			{
				skills.add(skill);
			}
		}
	}
}

package com.cooldownoverlays;

public enum BorderStyle
{
	ITEM_OUTLINE("Item outline"),
	INVENTORY_SLOT("Inventory slot");

	private final String label;

	BorderStyle(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.cooldownoverlays;

/** Client-thread state for a server-confirmed cooldown, measured in game ticks. */
final class Cooldown
{
	static final long TICK_NANOS = 600_000_000L;
	private boolean active;
	private boolean known;
	private int remainingTicks;
	private int totalTicks;
	private long sampledAtNanos;
	private boolean ready;
	private long readyAtNanos;

	void start(int ticks, int durationTicks, long nowNanos)
	{
		ready = false;
		active = true;
		known = true;
		remainingTicks = ticks;
		totalTicks = Math.max(ticks, durationTicks);
		sampledAtNanos = nowNanos;
	}

	void startUnknown(long nowNanos)
	{
		ready = false;
		active = true;
		known = false;
		remainingTicks = 0;
		totalTicks = 0;
		sampledAtNanos = nowNanos;
	}

	void tick(long nowNanos)
	{
		tick(nowNanos, 1);
	}

	void tick(long nowNanos, int minimumTicks)
	{
		if (active && known)
		{
			// The server flag remains authoritative, even if a tick arrives late.
			remainingTicks = Math.max(Math.max(1, minimumTicks), remainingTicks - 1);
		}
		sampledAtNanos = nowNanos;
	}

	void clear()
	{
		ready = false;
		active = false;
		known = false;
		remainingTicks = 0;
		totalTicks = 0;
	}

	void finish(long nowNanos)
	{
		setReady(nowNanos);
	}

	void setReady(long nowNanos)
	{
		if (!ready)
		{
			clear();
			ready = true;
			readyAtNanos = nowNanos;
		}
	}

	double getFinishedAgeSeconds(long nowNanos)
	{
		return ready && nowNanos >= readyAtNanos
			? (nowNanos - readyAtNanos) / 1_000_000_000.0 : -1;
	}

	boolean isReady()
	{
		return ready;
	}

	void restartReadyAnimation(long nowNanos)
	{
		if (ready)
		{
			readyAtNanos = nowNanos;
		}
	}

	boolean isActive()
	{
		return active;
	}

	boolean isKnown()
	{
		return known;
	}

	int getTotalTicks()
	{
		return totalTicks;
	}

	double getRemainingSeconds(long nowNanos)
	{
		if (!active || !known)
		{
			return 0;
		}
		// Smooth within one game tick only; stalled clients cannot imply readiness.
		long elapsed = Math.min(TICK_NANOS, Math.max(0, nowNanos - sampledAtNanos));
		long remaining = remainingTicks * TICK_NANOS - elapsed;
		return Math.max(0.001, remaining / 1_000_000_000.0);
	}

	double getRemainingFraction(long nowNanos)
	{
		if (!active)
		{
			return 0;
		}
		if (!known)
		{
			return 1;
		}
		return Math.min(1, getRemainingSeconds(nowNanos) / (totalTicks * 0.6));
	}
}

package com.cooldownoverlays;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(CooldownOverlaysConfig.GROUP)
public interface CooldownOverlaysConfig extends Config
{
	String GROUP = "cooldown-overlays";

	@ConfigSection(
		name = "Hearts",
		description = "Choose which heart items display their shared cooldown",
		position = 10
	)
	String heartsSection = "hearts";

	@ConfigSection(
		name = "Potion cooldowns",
		description = "Choose which potions show their reuse cooldown",
		position = 11
	)
	String potionCooldownsSection = "potionCooldowns";

	@ConfigSection(
		name = "Potion effects",
		description = "Show the remaining effect duration on potion items in your inventory",
		position = 12
	)
	String potionEffectsSection = "potionEffects";

	@ConfigSection(
		name = "Boost potions",
		description = "Choose actual skill levels to re-dose below; 0 disables a skill",
		position = 13
	)
	String boostPotionsSection = "boostPotions";

	@ConfigSection(
		name = "Animations",
		description = "Animate inventory icons when their items are ready to use",
		position = 5
	)
	String animationsSection = "animations";

	@ConfigSection(
		name = "Raid potions",
		description = "Choose which raid supplies show their remaining effect duration",
		position = 20
	)
	String raidPotionsSection = "raidPotions";

	@ConfigItem(
		keyName = "displayMode",
		name = "Display mode",
		description = "Show a timer, a circular sweep, or an item fill that reveals the original icon from bottom to top",
		position = 0
	)
	default DisplayMode displayMode()
	{
		return DisplayMode.BOTH;
	}

