package com.cooldownoverlays;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Cooldown Overlays",
	description = "Cooldowns, potion effect timers, and animated glows on inventory items",
	tags = {"cooldown", "timer", "heart", "potion", "boost", "raid", "inventory"}
)
public class CooldownOverlaysPlugin extends Plugin
{
	private static final String LIQUID_ADRENALINE_MESSAGE =
		"You drink some of the potion, reducing the energy cost of your special attacks.";
	private static final String SILK_DRESSING_MESSAGE = "You quickly apply the dressing to your wounds.";
	private static final String BLESSED_CRYSTAL_SCARAB_MESSAGE = "You crack the crystal in your hand.";

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private InventoryCooldownOverlay inventoryOverlay;
	@Inject
	private CooldownTracker tracker;
	@Inject
	private PotionTimers potionTimers;
	@Inject
	private BoostPotionTimers boostPotionTimers;
	@Inject
	private CooldownOverlaysConfig config;
	@Inject
	private ConfigManager configManager;
	@Inject
	private ItemOutlineCache itemOutlines;
	private volatile boolean running;
	// Client-thread state: a queued startup callback must not replace a newer server sample.
	private boolean sampled;

	@Provides
	CooldownOverlaysConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CooldownOverlaysConfig.class);
	}

	@Override
	protected void startUp()
	{
		migrateAnimations();
		running = true;
		overlayManager.add(inventoryOverlay);
		clientThread.invoke(() ->
		{
			if (running && !sampled && client.getGameState() == GameState.LOGGED_IN)
			{
				sampleTimers();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		running = false;
		overlayManager.remove(inventoryOverlay);
		clientThread.invoke(() ->
		{
			clearTimers();
			itemOutlines.clear();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (!running)
		{
			return;
		}
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING
			|| state == GameState.CONNECTION_LOST || state == GameState.LOGGING_IN)
		{
			clearTimers();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (running && client.getGameState() == GameState.LOGGED_IN)
		{
			// GameTick runs after this server batch's var updates. Sampling once here
			// avoids subtracting a tick from a cooldown started in VarbitChanged.
			sampleTimers();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!running || client.getGameState() != GameState.LOGGED_IN
			|| (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM))
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());
		if (LIQUID_ADRENALINE_MESSAGE.equals(message))
		{
			// A successful second dose can refresh adrenaline without toggling its active flag.
			potionTimers.onLiquidAdrenalineDose();
		}
		else if (SILK_DRESSING_MESSAGE.equals(message))
		{
			potionTimers.onConfirmedUse(PotionEffect.SILK_DRESSING, System.nanoTime());
		}
		else if (BLESSED_CRYSTAL_SCARAB_MESSAGE.equals(message))
		{
			potionTimers.onConfirmedUse(PotionEffect.BLESSED_CRYSTAL_SCARAB, System.nanoTime());
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (running && client.getLocalPlayer() != null && event.getActor() == client.getLocalPlayer())
		{
			potionTimers.clearOnDeath();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (running && CooldownOverlaysConfig.GROUP.equals(event.getGroup())
			&& (event.getKey().equals("animateActivation") || event.getKey().equals("animationMode")
				|| event.getKey().equals("animationDuration") || event.getKey().equals("animationBorderStyle")
				|| event.getKey().equals("animationBorderWidth")))
		{
			clientThread.invoke(() ->
			{
				if (running && config.animateWhenReady())
				{
					long nowNanos = System.nanoTime();
					tracker.getHeart().restartReadyAnimation(nowNanos);
					for (PotionEffect effect : PotionEffect.values())
					{
						potionTimers.get(effect).restartReadyAnimation(nowNanos);
					}
					for (BoostPotion potion : BoostPotion.values())
					{
						boostPotionTimers.get(potion).restartReadyAnimation(nowNanos);
					}
				}
			});
		}
	}

	private void migrateAnimations()
	{
		// Keep the existing activation key, duration, and color. Fold the removed
		// running-border toggle into the single ready-animation preference once.
		String oldBorder = configManager.getConfiguration(CooldownOverlaysConfig.GROUP, "animateBorder");
		if (oldBorder != null)
		{
			if (Boolean.parseBoolean(oldBorder))
			{
				configManager.setConfiguration(CooldownOverlaysConfig.GROUP, "animateActivation", true);
			}
			configManager.unsetConfiguration(CooldownOverlaysConfig.GROUP, "animateBorder");
		}
	}

	private void sampleTimers()
	{
		long nowNanos = System.nanoTime();
		tracker.tick(heartValue(), nowNanos);
		potionTimers.tick(client, nowNanos);
		boostPotionTimers.tick(client, config, nowNanos);
		sampled = true;
	}

	private void clearTimers()
	{
		tracker.clear();
		potionTimers.clear();
		boostPotionTimers.clear();
		sampled = false;
	}

	private int heartValue()
	{
		return client.getVarbitValue(VarbitID.IMBUED_HEART_TIMER);
	}
}

package com.cooldownoverlays;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.Arc2D;
import java.awt.geom.Rectangle2D;
import java.awt.geom.RoundRectangle2D;
import javax.inject.Inject;

/** Draws icon overlays, preserving the caller's clipping and graphics state. */
final class CooldownRenderer
{
	private static final Font TIMER_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 12);
	private final CooldownOverlaysConfig config;

	@Inject
	CooldownRenderer(CooldownOverlaysConfig config)
	{
		this.config = config;
	}

	void render(Graphics2D graphics, Rectangle bounds, Cooldown cooldown, long nowNanos)
	{
		render(graphics, bounds, cooldown, nowNanos, null);
	}

	void render(Graphics2D graphics, Rectangle bounds, Cooldown cooldown, long nowNanos, Shape itemOutline)
	{
		if (!isVisible(cooldown, nowNanos) || bounds.width <= 0 || bounds.height <= 0)
		{
			return;
		}

		boolean known = cooldown.isKnown();
		double seconds = known ? cooldown.getRemainingSeconds(nowNanos) : 0;
		if (cooldown.isActive() && known && seconds <= 0)
		{
			return;
		}

		Graphics2D iconGraphics = (Graphics2D) graphics.create();
		try
		{
			// A silhouette stroke can extend slightly beyond its source sprite. Keep the
			// inherited widget clip, while tile borders and timers stay inside their icon.
			if (cooldown.isActive() || config.animationBorderStyle() != BorderStyle.ITEM_OUTLINE)
			{
				iconGraphics.clip(bounds);
			}
			iconGraphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			DisplayMode mode = config.displayMode();
			if (cooldown.isActive() && (!known || mode != DisplayMode.TIMER))
			{
				double fraction = known ? cooldown.getRemainingFraction(nowNanos) : 1;
				if (mode.usesItemFill())
				{
					drawItemFill(iconGraphics, bounds, itemOutline, fraction, known);
				}
				else
				{
					drawCircle(iconGraphics, bounds, fraction, known);
				}
			}
			if (cooldown.isReady())
			{
				double opacity = 1;
				if (config.animationMode() == AnimationMode.TIMED)
				{
					double duration = Math.max(1, config.animationDuration());
					double age = cooldown.getFinishedAgeSeconds(nowNanos);
					opacity = Math.min(1, (duration - age) / Math.min(0.5, duration));
				}
				drawAnimatedBorder(iconGraphics, bounds, itemOutline, nowNanos, opacity);
			}
			// Draw text last so glows never obscure the timer.
			if (cooldown.isActive() && (!known || mode.showsTimer()))
			{
				drawTimer(iconGraphics, bounds, known ? formatSeconds(seconds) : "?");
			}
		}
		finally
		{
			iconGraphics.dispose();
		}
	}

	boolean isVisible(Cooldown cooldown, long nowNanos)
	{
		if (cooldown.isActive())
		{
			return true;
		}
		if (!config.animateWhenReady() || !cooldown.isReady())
		{
			return false;
		}
		double age = cooldown.getFinishedAgeSeconds(nowNanos);
		return age >= 0 && (config.animationMode() == AnimationMode.PERMANENT
			|| age < Math.max(1, config.animationDuration()));
	}

	private void drawAnimatedBorder(Graphics2D graphics, Rectangle bounds, Shape itemOutline, long nowNanos,
		double opacity)
	{
		int width = Math.max(1, Math.min(6, config.animationBorderWidth()));
		Shape border;
		if (config.animationBorderStyle() == BorderStyle.ITEM_OUTLINE)
		{
			if (itemOutline == null)
			{
				return;
			}
			border = itemOutline;
		}
		else
		{
			double inset = (width + 3) / 2.0 + 0.5;
			if (bounds.width <= inset * 2 || bounds.height <= inset * 2)
			{
				return;
			}
			border = new RoundRectangle2D.Double(inset, inset,
				bounds.width - inset * 2, bounds.height - inset * 2, 5, 5);
		}
		graphics.translate(bounds.x, bounds.y);
		double phase = Math.floorMod(nowNanos, 1_200_000_000L) / 1_200_000_000.0;
		Color color = config.animationColor();
		double pulse = 0.65 + 0.35 * Math.sin(phase * Math.PI * 2);
		// Soft edges follow the same contour as the selected-width core.
		graphics.setStroke(new BasicStroke(width + 3, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(withOpacity(color, opacity * pulse * 0.08));
		graphics.draw(border);
		graphics.setStroke(new BasicStroke(width + 1, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(withOpacity(color, opacity * pulse * 0.16));
		graphics.draw(border);
		graphics.setStroke(new BasicStroke(width, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.setColor(withOpacity(color, opacity * pulse * 0.4));
		graphics.draw(border);
		graphics.setStroke(new BasicStroke(width,
			BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 10,
			new float[]{5, 12}, (float) (phase * 17)));
		graphics.setColor(withOpacity(color, opacity * pulse));
		graphics.draw(border);
	}

	private static Color withOpacity(Color color, double opacity)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(),
			(int) Math.round(color.getAlpha() * Math.max(0, Math.min(1, opacity))));
	}

	private void drawItemFill(Graphics2D graphics, Rectangle bounds, Shape silhouette,
		double fraction, boolean known)
	{
		if (silhouette == null)
		{
			return;
		}
		Rectangle2D itemBounds = silhouette.getBounds2D();
		double remaining = Math.max(0, Math.min(1, fraction));
		if (itemBounds.isEmpty() || remaining <= 0)
		{
			return;
		}
		Graphics2D fillGraphics = (Graphics2D) graphics.create();
		try
		{
			fillGraphics.translate(bounds.x, bounds.y);
			fillGraphics.clip(silhouette);
			fillGraphics.setColor(progressShade(known));
			// Only shade unrevealed item pixels. The original full-colour icon shows
			// below the rising boundary, including its texture and transparent holes.
			fillGraphics.fill(new Rectangle2D.Double(itemBounds.getX(), itemBounds.getY(),
				itemBounds.getWidth(), itemBounds.getHeight() * remaining));
		}
		finally
		{
			fillGraphics.dispose();
		}
	}

	private Color progressShade(boolean known)
	{
		int opacity = Math.max(0, Math.min(100, config.circleOpacity()));
		int alpha = (int) Math.round(opacity * 255 / 100.0 * (known ? 1 : 0.5));
		return new Color(0, 0, 0, alpha);
	}

	private void drawCircle(Graphics2D graphics, Rectangle bounds, double fraction, boolean known)
	{
		double remaining = Math.max(0, Math.min(1, fraction));
		double diameter = Math.min(bounds.width, bounds.height) - 1;
		if (diameter <= 0 || remaining <= 0)
		{
			return;
		}
		graphics.setColor(progressShade(known));
		// Start fully shaded, then reveal clockwise from twelve o'clock.
		double startAngle = 90 - (1 - remaining) * 360;
		graphics.fill(new Arc2D.Double(
			bounds.getCenterX() - diameter / 2,
			bounds.getCenterY() - diameter / 2,
			diameter, diameter, startAngle, -360 * remaining, Arc2D.PIE));
	}

	private void drawTimer(Graphics2D graphics, Rectangle bounds, String text)
	{
		Font font = TIMER_FONT;
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics();
		// Keep long minute timers legible on small or resized spell icons.
		if (metrics.stringWidth(text) > bounds.width - 2)
		{
			float size = Math.max(8, font.getSize2D() * (bounds.width - 2) / metrics.stringWidth(text));
			graphics.setFont(font.deriveFont(size));
			metrics = graphics.getFontMetrics();
		}
		int x = bounds.x + (bounds.width - metrics.stringWidth(text)) / 2;
		int y = bounds.y + (bounds.height - metrics.getAscent() - metrics.getDescent()) / 2 + metrics.getAscent();
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x - 1, y);
		graphics.drawString(text, x + 1, y);
		graphics.drawString(text, x, y - 1);
		graphics.drawString(text, x, y + 1);
		graphics.setColor(config.timerColor());
		graphics.drawString(text, x, y);
	}

	static String formatSeconds(double seconds)
	{
		long roundedSeconds = (long) Math.ceil(Math.max(0, seconds));
		if (roundedSeconds < 60)
		{
			return Long.toString(roundedSeconds);
		}
		long remainder = roundedSeconds % 60;
		return roundedSeconds / 60 + ":" + (remainder < 10 ? "0" : "") + remainder;
	}
}

package com.cooldownoverlays;

import javax.inject.Singleton;

/** Tracks the shared heart timer independently of display settings. */
@Singleton
final class CooldownTracker
{
	static final int HEART_BUCKET_TICKS = 10;
	static final int IMBUED_HEART_TICKS = 700;
	static final int SATURATED_HEART_TICKS = 500;
	private final Cooldown heart = new Cooldown();
	private int previousHeart;
	private boolean initialized;

	void initialize(int heartValue, long nowNanos)
	{
		clear();
		initialized = true;
		previousHeart = Math.max(0, heartValue);
		if (previousHeart > 0)
		{
			// Mid-cooldown login cannot identify which heart started the shared timer.
			heart.start(previousHeart * HEART_BUCKET_TICKS, IMBUED_HEART_TICKS, nowNanos);
		}
		else
		{
			heart.setReady(nowNanos);
		}
	}

	void tick(int heartValue, long nowNanos)
	{
		if (!initialized)
		{
			initialize(heartValue, nowNanos);
			return;
		}
		// An unchanged server bucket can also mean the cooldown is paused.
		heart.tick(nowNanos, (previousHeart - 1) * HEART_BUCKET_TICKS + 1);
		update(heartValue, nowNanos);
	}

	private void update(int heartValue, long nowNanos)
	{
		heartValue = Math.max(0, heartValue);
		if (heartValue == 0)
		{
			heart.finish(nowNanos);
		}
		else if (heartValue != previousHeart)
		{
			int ticks = heartValue * HEART_BUCKET_TICKS;
			int total = heart.getTotalTicks();
			if (heartValue > previousHeart || !heart.isActive())
			{
				total = ticks > SATURATED_HEART_TICKS ? IMBUED_HEART_TICKS : SATURATED_HEART_TICKS;
			}
			heart.start(ticks, total, nowNanos);
		}
		previousHeart = heartValue;
	}

	void clear()
	{
		heart.clear();
		previousHeart = 0;
		initialized = false;
	}

	Cooldown getHeart()
	{
		return heart;
	}
}

package com.cooldownoverlays;

public enum DisplayMode
{
	TIMER("Timer"),
	CIRCLE("Circular sweep"),
	BOTH("Timer and circular sweep"),
	ITEM_FILL("Item fill"),
	TIMER_AND_ITEM_FILL("Timer and item fill");

	private final String label;

	DisplayMode(String label)
	{
		this.label = label;
	}

	boolean usesItemFill()
	{
		return this == ITEM_FILL || this == TIMER_AND_ITEM_FILL;
	}

	boolean showsTimer()
	{
		return this == TIMER || this == BOTH || this == TIMER_AND_ITEM_FILL;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.cooldownoverlays;

import java.awt.Graphics2D;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

final class InventoryCooldownOverlay extends WidgetItemOverlay
{
	private final Client client;
	private final CooldownOverlaysConfig config;
	private final CooldownTracker tracker;
	private final PotionTimers potionTimers;
	private final BoostPotionTimers boostPotionTimers;
	private final CooldownRenderer renderer;
	private final ItemOutlineCache itemOutlines;

	@Inject
	InventoryCooldownOverlay(Client client, CooldownOverlaysConfig config, CooldownTracker tracker,
		PotionTimers potionTimers, BoostPotionTimers boostPotionTimers, CooldownRenderer renderer,
		ItemOutlineCache itemOutlines)
	{
		this.client = client;
		this.config = config;
		this.tracker = tracker;
		this.potionTimers = potionTimers;
		this.boostPotionTimers = boostPotionTimers;
		this.renderer = renderer;
		this.itemOutlines = itemOutlines;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		boolean enabled = itemId == ItemID.IMBUED_HEART && config.imbuedHeart()
			|| itemId == ItemID.SATURATED_HEART && config.saturatedHeart();
		if (enabled)
		{
			render(graphics, widgetItem, tracker.getHeart());
			return;
		}
		PotionItems.Family family = PotionItems.getFamily(itemId);
		if (family != null && family.isEnabled(config))
		{
			render(graphics, widgetItem, potionTimers.get(family.getEffect()));
		}
		BoostPotion boostPotion = BoostPotion.forItem(itemId);
		if (boostPotion != null && boostPotion.isEnabled(config))
		{
			render(graphics, widgetItem, boostPotionTimers.get(boostPotion));
		}
	}

	private void render(Graphics2D graphics, WidgetItem widgetItem, Cooldown cooldown)
	{
		long nowNanos = System.nanoTime();
		if (!renderer.isVisible(cooldown, nowNanos))
		{
			return;
		}
		boolean needsSilhouette = cooldown.isActive() && config.displayMode().usesItemFill()
			|| cooldown.isReady() && config.animationBorderStyle() == BorderStyle.ITEM_OUTLINE;
		Shape outline = needsSilhouette
			? itemOutlines.getOutline(widgetItem.getId(), widgetItem.getQuantity()) : null;
		renderer.render(graphics, widgetItem.getCanvasBounds(), cooldown, nowNanos, outline);
	}
}

package com.cooldownoverlays;

import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.SpritePixels;
import net.runelite.api.widgets.ItemQuantityMode;

/** Client-thread cache of item silhouettes in native sprite coordinates. */
@Singleton
final class ItemOutlineCache
{
	private static final int MAX_ENTRIES = 128;
	private final Client client;
	private final Map<Long, Shape> outlines = new LinkedHashMap<Long, Shape>(MAX_ENTRIES, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Long, Shape> eldest)
		{
			return size() > MAX_ENTRIES;
		}
	};

	@Inject
	ItemOutlineCache(Client client)
	{
		this.client = client;
	}

	Shape getOutline(int itemId, int quantity)
	{
		long key = ((long) itemId << 32) | (quantity & 0xffffffffL);
		Shape outline = outlines.get(key);
		if (outline != null)
		{
			return outline;
		}
		// Counts, the game's black border, and the drop shadow are not item pixels.
		SpritePixels sprite = client.createItemSprite(itemId, quantity, 0, 0,
			ItemQuantityMode.NEVER, false, Constants.CLIENT_DEFAULT_ZOOM);
		if (sprite == null)
		{
			return null;
		}
		outline = trace(sprite.toBufferedImage());
		if (outline != null)
		{
			outlines.put(key, outline);
		}
		return outline;
	}

	void clear()
	{
		outlines.clear();
	}

	static Shape trace(BufferedImage sprite)
	{
		if (sprite == null)
		{
			return null;
		}
		Path2D.Double runs = new Path2D.Double();
		boolean visible = false;
		for (int y = 0; y < sprite.getHeight(); y++)
		{
			int x = 0;
			while (x < sprite.getWidth())
			{
				while (x < sprite.getWidth() && (sprite.getRGB(x, y) >>> 24) == 0)
				{
					x++;
				}
				int start = x;
				while (x < sprite.getWidth() && (sprite.getRGB(x, y) >>> 24) != 0)
				{
					x++;
				}
				if (start < x)
				{
					visible = true;
					runs.moveTo(start, y);
					runs.lineTo(x, y);
					runs.lineTo(x, y + 1);
					runs.lineTo(start, y + 1);
					runs.closePath();
				}
			}
		}
		// Area removes shared row-run edges and retains holes and disconnected parts.
		return visible ? new Area(runs) : null;
	}
}

package com.cooldownoverlays;

import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;

/** Server counters and confirmed-use durations for item cooldowns and potion effects. */
enum PotionEffect
{
	SURGE(VarbitID.SURGE_POTION_TIMER, 10, 500),
	OVERLOAD(VarbitID.RAIDS_OVERLOAD_TIMER, 25, 500),
	NMZ_OVERLOAD(VarbitID.NZONE_OVERLOAD_POTION_EFFECTS, 25, 500),
	BLIGHTED_OVERLOAD(VarbitID.DEADMAN_OVERLOAD_POTION_EFFECTS, 25, 500),
	PRAYER_ENHANCE(VarbitID.RAIDS_PRAYERENHANCE_TIMER, 1, 0),
	SMELLING_SALTS(VarbitID.TOA_MIDRAIDLOOT_STATS_TIMER, 25, 800),
	LIQUID_ADRENALINE(VarbitID.TOA_MIDRAIDLOOT_ENERGY_ACTIVE, 1, 250),
	SILK_DRESSING(-1, 1, 100),
	BLESSED_CRYSTAL_SCARAB(-1, 1, 40),
	STAMINA(VarbitID.STAMINA_DURATION, 10, 200),
	GOADING(VarbitID.GOADING_POTION_TIMER, 6, 600),
	MENAPHITE_REMEDY(VarbitID.STATRENEWAL_POTION_TIMER, 25, 500),
	MOONLIGHT(VarbitID.MOONLIGHT_POTION_TIME, 1, 500),
	PRAYER_REGENERATION(VarbitID.PRAYER_REGENERATION_POTION_TIMER, 12, 800),
	ANTIFIRE(VarbitID.ANTIFIRE_POTION, 30, 600),
	SUPER_ANTIFIRE(VarbitID.SUPER_ANTIFIRE_POTION, 20, 300),
	ANTIPOISON(VarPlayerID.POISON, 30, 0),
	ANTIVENOM(VarPlayerID.POISON, 30, 0),
	DIVINE_ATTACK(VarbitID.DIVINEATTACK_POTION_TIME, 1, 500),
	DIVINE_STRENGTH(VarbitID.DIVINESTRENGTH_POTION_TIME, 1, 500),
	DIVINE_DEFENCE(VarbitID.DIVINEDEFENCE_POTION_TIME, 1, 500),
	DIVINE_RANGING(VarbitID.DIVINERANGE_POTION_TIME, 1, 500),
	DIVINE_MAGIC(VarbitID.DIVINEMAGIC_POTION_TIME, 1, 500),
	DIVINE_COMBAT(VarbitID.DIVINECOMBAT_POTION_TIME, 1, 500),
	DIVINE_BASTION(VarbitID.DIVINEBASTION_POTION_TIME, 1, 500),
	DIVINE_BATTLEMAGE(VarbitID.DIVINEBATTLEMAGE_POTION_TIME, 1, 500);

	private static final int VENOM_IMMUNITY_CUTOFF = -38;
	private final int variableId;
	private final int bucketTicks;
	private final int standardTicks;

	PotionEffect(int variableId, int bucketTicks, int standardTicks)
	{
		this.variableId = variableId;
		this.bucketTicks = bucketTicks;
		this.standardTicks = standardTicks;
	}

	int read(Client client)
	{
		if (isConfirmedUseEffect())
		{
			return 0;
		}
		if ((this == OVERLOAD || this == PRAYER_ENHANCE)
			&& client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) != 1)
		{
			return 0;
		}
		if (this == ANTIVENOM || this == ANTIPOISON)
		{
			return client.getVarpValue(variableId);
		}
		if (this == STAMINA && client.getVarbitValue(VarbitID.STAMINA_ACTIVE) != 1)
		{
			return 0;
		}
		if (this == MOONLIGHT)
		{
			int ticks = client.getVarbitValue(variableId);
			int defenceTicks = client.getVarbitValue(VarbitID.DIVINEDEFENCE_POTION_TIME);
			// Re-dosing can leave the Moonlight timer one tick behind its linked
			// Defence timer. Do not infer Moonlight from an unrelated divine dose.
			if (ticks > 0 && defenceTicks > ticks + 1)
			{
				// A longer actual divine effect supersedes the Moonlight Defence timer.
				return 0;
			}
			return ticks > 0 && defenceTicks == ticks + 1 ? ticks + 1 : ticks;
		}
		return client.getVarbitValue(variableId);
	}

	int remainingBuckets(int rawValue)
	{
		if (this == ANTIPOISON)
		{
			// Venom protection also prevents poison, including its eventual poison-only tail.
			return rawValue < 0 ? -rawValue : 0;
		}
		if (this == ANTIVENOM)
		{
			// Values -38 through -1 are the poison-immunity tail, not venom protection.
			return rawValue >= VENOM_IMMUNITY_CUTOFF ? 0 : -(rawValue - VENOM_IMMUNITY_CUTOFF);
		}
		return Math.max(0, rawValue);
	}

	int getBucketTicks()
	{
		return bucketTicks;
	}

	int getStandardTicks()
	{
		return standardTicks;
	}

	boolean preservesBucketPhase()
	{
		return this == OVERLOAD || this == NMZ_OVERLOAD || this == BLIGHTED_OVERLOAD
			|| this == PRAYER_ENHANCE || this == ANTIFIRE || this == SUPER_ANTIFIRE
			|| this == ANTIPOISON || this == ANTIVENOM;
	}

	boolean hasBucketPhase(int rawValue)
	{
		// Re-dosing antivenom shares the poison counter's existing 30-tick cadence.
		return this == ANTIVENOM || this == ANTIPOISON ? rawValue != 0 : rawValue > 0;
	}

	boolean isConfirmedUseEffect()
	{
		return this == SILK_DRESSING || this == BLESSED_CRYSTAL_SCARAB;
	}
}

package com.cooldownoverlays;

import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

/** Tracks item cooldowns and potion protection independently of display settings. */
@Singleton
final class PotionTimers
{
	private final Map<PotionEffect, State> states = new EnumMap<>(PotionEffect.class);
	private final Set<PotionEffect> pendingConfirmedUses = EnumSet.noneOf(PotionEffect.class);
	private boolean initialized;
	private int tickCount;
	private boolean liquidAdrenalineDose;

	PotionTimers()
	{
		for (PotionEffect effect : PotionEffect.values())
		{
			states.put(effect, new State());
		}
	}

	void initialize(Client client, long nowNanos)
	{
		initialize(read(client), client.getVarbitValue(VarbitID.RAIDS_PRAYERENHANCE_RATE), nowNanos);
		suppressUnavailableRaidEffects(client);
	}

	void tick(Client client, long nowNanos)
	{
		tick(read(client), client.getVarbitValue(VarbitID.RAIDS_PRAYERENHANCE_RATE), nowNanos);
		suppressUnavailableRaidEffects(client);
	}

	void onLiquidAdrenalineDose()
	{
		// A confirmed drink can refresh the effect without changing its active flag.
		liquidAdrenalineDose = true;
	}

	void onConfirmedUse(PotionEffect effect, long nowNanos)
	{
		if (!effect.isConfirmedUseEffect())
		{
			throw new IllegalArgumentException("Effect does not use a confirmed-use timer: " + effect);
		}
		State state = states.get(effect);
		state.available = true;
		state.cooldown.start(effect.getStandardTicks(), effect.getStandardTicks(), nowNanos);
		state.knownUntilTick = tickCount + effect.getStandardTicks();
		// The next sample belongs to this message's server batch. Start that sample
		// at full duration instead of prematurely deducting one game tick.
		pendingConfirmedUses.add(effect);
	}

	void initialize(Map<PotionEffect, Integer> samples, long nowNanos)
	{
		initialize(samples, 1, nowNanos);
	}

	void initialize(Map<PotionEffect, Integer> samples, int prayerEnhanceRate, long nowNanos)
	{
		Set<PotionEffect> pendingUses = EnumSet.noneOf(PotionEffect.class);
		pendingUses.addAll(pendingConfirmedUses);
		clear();
		pendingConfirmedUses.addAll(pendingUses);
		initialized = true;
		for (PotionEffect effect : PotionEffect.values())
		{
			if (effect.isConfirmedUseEffect())
			{
				updateConfirmedUse(effect, nowNanos);
			}
			else
			{
				update(effect, samples.getOrDefault(effect, 0), bucketTicks(effect, prayerEnhanceRate), nowNanos, true);
			}
		}
	}

	void tick(Map<PotionEffect, Integer> samples, long nowNanos)
	{
		tick(samples, 1, nowNanos);
	}

	void tick(Map<PotionEffect, Integer> samples, int prayerEnhanceRate, long nowNanos)
	{
		if (!initialized)
		{
			boolean confirmedDose = liquidAdrenalineDose;
			initialize(samples, prayerEnhanceRate, nowNanos);
			if (confirmedDose)
			{
				liquidAdrenalineDose = true;
				update(PotionEffect.LIQUID_ADRENALINE,
					samples.getOrDefault(PotionEffect.LIQUID_ADRENALINE, 0), 1, nowNanos, false);
				liquidAdrenalineDose = false;
			}
			return;
		}
		tickCount++;
		for (PotionEffect effect : PotionEffect.values())
		{
			if (effect.isConfirmedUseEffect())
			{
				updateConfirmedUse(effect, nowNanos);
				continue;
			}
			int rawValue = samples.getOrDefault(effect, 0);
			int buckets = effect.remainingBuckets(rawValue);
			int bucketTicks = bucketTicks(effect, prayerEnhanceRate);
			int minimumTicks = Math.max(1, (buckets - 1) * bucketTicks + 1);
			// Some cooldowns pause in encounters. Never interpolate into another server bucket.
			states.get(effect).cooldown.tick(nowNanos, minimumTicks);
			update(effect, rawValue, bucketTicks, nowNanos, false);
		}
		liquidAdrenalineDose = false;
	}

	private void updateConfirmedUse(PotionEffect effect, long nowNanos)
	{
		State state = states.get(effect);
		if (pendingConfirmedUses.remove(effect))
		{
			state.available = true;
			state.cooldown.start(effect.getStandardTicks(), effect.getStandardTicks(), nowNanos);
			state.knownUntilTick = tickCount + effect.getStandardTicks();
		}
		else if (state.cooldown.isActive())
		{
			if (tickCount >= state.knownUntilTick)
			{
				state.cooldown.setReady(nowNanos);
			}
			else
			{
				state.cooldown.tick(nowNanos);
			}
		}
	}

	private void update(PotionEffect effect, int rawValue, int bucketTicks, long nowNanos, boolean initial)
	{
		State state = states.get(effect);
		initial |= !state.available;
		state.available = true;
		int buckets = bucketTicks == 0 ? 0 : effect.remainingBuckets(rawValue);
		boolean rateChanged = bucketTicks != state.previousBucketTicks;
		boolean changed = rawValue != state.previousRaw || rateChanged;
		if (effect == PotionEffect.LIQUID_ADRENALINE)
		{
			if (buckets == 0)
			{
				state.knownUntilTick = -1;
				state.cooldown.setReady(nowNanos);
			}
			else if (!initial && (liquidAdrenalineDose || state.previousRaw <= 0))
			{
				state.cooldown.start(effect.getStandardTicks(), effect.getStandardTicks(), nowNanos);
				state.knownUntilTick = tickCount + effect.getStandardTicks();
			}
			else if (initial || !state.cooldown.isActive()
				|| (state.cooldown.isKnown() && tickCount >= state.knownUntilTick))
			{
				// The flag cannot recover an existing duration or a missed refresh.
				state.cooldown.startUnknown(nowNanos);
				state.knownUntilTick = -1;
			}
			state.previousRaw = rawValue;
			state.previousBucketTicks = bucketTicks;
			return;
		}
		if (effect.preservesBucketPhase() && (initial || changed))
		{
			if (!effect.hasBucketPhase(rawValue))
			{
				state.nextBucketTick = -1;
			}
			else if (rateChanged || state.nextBucketTick <= tickCount)
			{
				state.nextBucketTick = tickCount + bucketTicks;
			}
		}
		if (buckets == 0)
		{
			state.cooldown.setReady(nowNanos);
		}
		else if (initial || changed || !state.cooldown.isActive())
		{
			int ticks = buckets * bucketTicks;
			if (effect.preservesBucketPhase())
			{
				// Drinking again adds counter units without restarting the underlying cadence.
				ticks = (buckets - 1) * bucketTicks
					+ Math.max(1, state.nextBucketTick - tickCount);
			}
			int total = state.cooldown.getTotalTicks();
			if (!state.cooldown.isActive() || rateChanged || buckets > effect.remainingBuckets(state.previousRaw))
			{
				// Extended and stacked effects can exceed their standard potion duration.
				// Antivenom's initial counter also distinguishes its short and extended variants.
				total = Math.max(effect.getStandardTicks(), ticks);
			}
			state.cooldown.start(ticks, total, nowNanos);
		}
		state.previousRaw = rawValue;
		state.previousBucketTicks = bucketTicks;
	}

	void clear()
	{
		for (State state : states.values())
		{
			clear(state);
		}
		tickCount = 0;
		initialized = false;
		liquidAdrenalineDose = false;
		pendingConfirmedUses.clear();
	}

	void clearOnDeath()
	{
		for (PotionEffect effect : PotionEffect.values())
		{
			if (effect.isConfirmedUseEffect())
			{
				clear(states.get(effect));
				pendingConfirmedUses.remove(effect);
			}
		}
	}

	Cooldown get(PotionEffect effect)
	{
		return states.get(effect).cooldown;
	}

	private void suppressUnavailableRaidEffects(Client client)
	{
		if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) != 1)
		{
			// Inactive Chambers counters outside the raid do not indicate usable supplies.
			clear(states.get(PotionEffect.OVERLOAD));
			clear(states.get(PotionEffect.PRAYER_ENHANCE));
		}
	}

	private static void clear(State state)
	{
		state.cooldown.clear();
		state.available = false;
		state.previousRaw = 0;
		state.previousBucketTicks = 0;
		state.nextBucketTick = -1;
		state.knownUntilTick = -1;
	}

	private static Map<PotionEffect, Integer> read(Client client)
	{
		Map<PotionEffect, Integer> samples = new EnumMap<>(PotionEffect.class);
		for (PotionEffect effect : PotionEffect.values())
		{
			samples.put(effect, effect.read(client));
		}
		return samples;
	}

	private static int bucketTicks(PotionEffect effect, int prayerEnhanceRate)
	{
		// The game's buff bar multiplies this counter by its tier-dependent refresh rate.
		return effect == PotionEffect.PRAYER_ENHANCE ? Math.max(0, prayerEnhanceRate) : effect.getBucketTicks();
	}

	private static final class State
	{
		private final Cooldown cooldown = new Cooldown();
		private boolean available;
		private int previousRaw;
		private int previousBucketTicks;
		private int nextBucketTick = -1;
		private int knownUntilTick = -1;
	}
}

package com.cooldownoverlays;

import java.lang.reflect.Proxy;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class AdditionalPotionTimersTest
{
	private static final double DELTA = 0.000001;
	private static final long START = 1_000_000_000L;
	private final PotionTimers timers = new PotionTimers();

	@Test
	public void newServerCountersUseTheirOwnRatesAndDurations()
	{
		Map<PotionEffect, Integer> samples = new EnumMap<>(PotionEffect.class);
		samples.put(PotionEffect.GOADING, 100);
		samples.put(PotionEffect.MENAPHITE_REMEDY, 20);
		samples.put(PotionEffect.MOONLIGHT, 500);
		samples.put(PotionEffect.PRAYER_REGENERATION, 66);
		timers.initialize(samples, START);

		assertEquals(360, remaining(PotionEffect.GOADING, 0), DELTA);
		assertEquals(300, remaining(PotionEffect.MENAPHITE_REMEDY, 0), DELTA);
		assertEquals(300, remaining(PotionEffect.MOONLIGHT, 0), DELTA);
		assertEquals(475.2, remaining(PotionEffect.PRAYER_REGENERATION, 0), DELTA);
		assertEquals(600, timers.get(PotionEffect.GOADING).getTotalTicks());
		assertEquals(500, timers.get(PotionEffect.MENAPHITE_REMEDY).getTotalTicks());
		assertEquals(500, timers.get(PotionEffect.MOONLIGHT).getTotalTicks());
		assertEquals(800, timers.get(PotionEffect.PRAYER_REGENERATION).getTotalTicks());
	}

	@Test
	public void newCountersRemainAuthoritativeWhenPausedAndClearToReady()
	{
		Map<PotionEffect, Integer> samples = new EnumMap<>(PotionEffect.class);
		samples.put(PotionEffect.GOADING, 1);
		samples.put(PotionEffect.MENAPHITE_REMEDY, 1);
		samples.put(PotionEffect.PRAYER_REGENERATION, 1);
		timers.initialize(samples, START);
		for (int tick = 1; tick <= 50; tick++)
		{
			timers.tick(samples, atTick(tick));
		}
		for (PotionEffect effect : samples.keySet())
		{
			assertTrue(effect.name(), timers.get(effect).isActive());
			assertFalse(effect.name(), timers.get(effect).isReady());
			assertEquals(0.6, remaining(effect, 50), DELTA);
		}
		timers.tick(Map.of(), atTick(51));
		for (PotionEffect effect : samples.keySet())
		{
			assertFalse(effect.name(), timers.get(effect).isActive());
			assertTrue(effect.name(), timers.get(effect).isReady());
		}
	}

	@Test
	public void overloadSourcesHaveIndependentTimersAndRefreshPhases()
	{
		Map<PotionEffect, Integer> samples = new EnumMap<>(PotionEffect.class);
		samples.put(PotionEffect.OVERLOAD, 20);
		samples.put(PotionEffect.NMZ_OVERLOAD, 10);
		samples.put(PotionEffect.BLIGHTED_OVERLOAD, 5);
		timers.initialize(samples, START);
		for (int tick = 1; tick < 10; tick++)
		{
			timers.tick(samples, atTick(tick));
		}
		samples.put(PotionEffect.NMZ_OVERLOAD, 20);
		timers.tick(samples, atTick(10));

		assertEquals(294, remaining(PotionEffect.NMZ_OVERLOAD, 10), DELTA);
		assertEquals(294, remaining(PotionEffect.OVERLOAD, 10), DELTA);
		assertEquals(69, remaining(PotionEffect.BLIGHTED_OVERLOAD, 10), DELTA);
		samples.put(PotionEffect.OVERLOAD, 0);
		timers.tick(samples, atTick(11));
		assertTrue(timers.get(PotionEffect.OVERLOAD).isReady());
		assertTrue(timers.get(PotionEffect.NMZ_OVERLOAD).isActive());
		assertTrue(timers.get(PotionEffect.BLIGHTED_OVERLOAD).isActive());
	}

	@Test
	public void poisonImmunityCoversTheFullCounterWhileVenomTracksOnlyItsStage()
	{
		Map<PotionEffect, Integer> samples = poison(-39);
		timers.initialize(samples, START);
		assertEquals(18, remaining(PotionEffect.ANTIVENOM, 0), DELTA);
		assertEquals(702, remaining(PotionEffect.ANTIPOISON, 0), DELTA);
		for (int tick = 1; tick < 30; tick++)
		{
			timers.tick(samples, atTick(tick));
		}
		timers.tick(poison(-38), atTick(30));

		assertTrue(timers.get(PotionEffect.ANTIVENOM).isReady());
		assertTrue(timers.get(PotionEffect.ANTIPOISON).isActive());
		assertEquals(684, remaining(PotionEffect.ANTIPOISON, 30), DELTA);
	}

	@Test
	public void poisonImmunityBoundariesHandleTheFinalBucketAndNoProtection()
	{
		timers.initialize(poison(-1), START);
		assertEquals(18, remaining(PotionEffect.ANTIPOISON, 0), DELTA);
		assertTrue(timers.get(PotionEffect.ANTIVENOM).isReady());
		timers.tick(poison(0), atTick(1));
		assertTrue(timers.get(PotionEffect.ANTIPOISON).isReady());
		timers.tick(poison(10), atTick(2));
		assertTrue(timers.get(PotionEffect.ANTIPOISON).isReady());
		assertTrue(timers.get(PotionEffect.ANTIVENOM).isReady());
	}

	@Test
	public void poisonRedosingRetainsItsCadenceAcrossTheVenomBoundary()
	{
		timers.initialize(poison(-38), START);
		for (int tick = 1; tick < 10; tick++)
		{
			timers.tick(poison(-38), atTick(tick));
		}
		timers.tick(poison(-48), atTick(10));
		assertEquals(174, remaining(PotionEffect.ANTIVENOM, 10), DELTA);
		assertEquals(858, remaining(PotionEffect.ANTIPOISON, 10), DELTA);
		timers.tick(poison(0), atTick(11));
		timers.tick(poison(-48), atTick(12));
		assertEquals(180, remaining(PotionEffect.ANTIVENOM, 12), DELTA);
		assertEquals(864, remaining(PotionEffect.ANTIPOISON, 12), DELTA);
	}

	@Test
	public void clientReadsNewCountersAndKeepsAllOverloadSourcesSeparate()
	{
		Map<Integer, Integer> varbits = new HashMap<>();
		varbits.put(VarbitID.GOADING_POTION_TIMER, 100);
		varbits.put(VarbitID.STATRENEWAL_POTION_TIMER, 20);
		varbits.put(VarbitID.MOONLIGHT_POTION_TIME, 499);
		varbits.put(VarbitID.DIVINEDEFENCE_POTION_TIME, 500);
		varbits.put(VarbitID.PRAYER_REGENERATION_POTION_TIMER, 66);
		varbits.put(VarbitID.RAIDS_CLIENT_INDUNGEON, 1);
		varbits.put(VarbitID.RAIDS_OVERLOAD_TIMER, 20);
		varbits.put(VarbitID.NZONE_OVERLOAD_POTION_EFFECTS, 10);
		varbits.put(VarbitID.DEADMAN_OVERLOAD_POTION_EFFECTS, 5);
		Client client = client(varbits, Map.of(VarPlayerID.POISON, -48));
		timers.initialize(client, START);

		assertEquals(360, remaining(PotionEffect.GOADING, 0), DELTA);
		assertEquals(300, remaining(PotionEffect.MENAPHITE_REMEDY, 0), DELTA);
		assertEquals(300, remaining(PotionEffect.MOONLIGHT, 0), DELTA);
		assertEquals(475.2, remaining(PotionEffect.PRAYER_REGENERATION, 0), DELTA);
		assertEquals(300, remaining(PotionEffect.OVERLOAD, 0), DELTA);
		assertEquals(150, remaining(PotionEffect.NMZ_OVERLOAD, 0), DELTA);
		assertEquals(75, remaining(PotionEffect.BLIGHTED_OVERLOAD, 0), DELTA);
		assertEquals(864, remaining(PotionEffect.ANTIPOISON, 0), DELTA);
		assertEquals(180, remaining(PotionEffect.ANTIVENOM, 0), DELTA);
		varbits.put(VarbitID.RAIDS_CLIENT_INDUNGEON, 0);
		timers.tick(client, atTick(1));
		assertFalse(timers.get(PotionEffect.OVERLOAD).isActive());
		assertFalse(timers.get(PotionEffect.OVERLOAD).isReady());
		assertTrue(timers.get(PotionEffect.NMZ_OVERLOAD).isActive());
		assertTrue(timers.get(PotionEffect.BLIGHTED_OVERLOAD).isActive());
	}

	@Test
	public void divineDefenceAloneCannotInventAMoonlightEffect()
	{
		Map<Integer, Integer> varbits = new HashMap<>();
		varbits.put(VarbitID.DIVINEDEFENCE_POTION_TIME, 1);
		timers.initialize(client(varbits, Map.of()), START);
		assertTrue(timers.get(PotionEffect.MOONLIGHT).isReady());
		assertFalse(timers.get(PotionEffect.MOONLIGHT).isActive());
	}

	@Test
	public void anActualDivineDefenceDoseOverridesTheMoonlightTimer()
	{
		Map<Integer, Integer> varbits = new HashMap<>();
		varbits.put(VarbitID.MOONLIGHT_POTION_TIME, 300);
		varbits.put(VarbitID.DIVINEDEFENCE_POTION_TIME, 301);
		Client client = client(varbits, Map.of());
		timers.initialize(client, START);
		assertEquals(180.6, remaining(PotionEffect.MOONLIGHT, 0), DELTA);
		varbits.put(VarbitID.DIVINEDEFENCE_POTION_TIME, 500);
		timers.tick(client, atTick(1));

		assertFalse(timers.get(PotionEffect.MOONLIGHT).isActive());
		assertTrue(timers.get(PotionEffect.MOONLIGHT).isReady());
		assertTrue(timers.get(PotionEffect.DIVINE_DEFENCE).isActive());
		assertEquals(300, remaining(PotionEffect.DIVINE_DEFENCE, 1), DELTA);
	}

	@Test
	public void chatOnlyEffectsStayHiddenUntilConfirmed()
	{
		timers.initialize(Map.of(), START);
		timers.tick(Map.of(), atTick(1));
		assertUnavailable(PotionEffect.SILK_DRESSING);
		assertUnavailable(PotionEffect.BLESSED_CRYSTAL_SCARAB);
	}

	@Test
	public void confirmationBeforeFirstSampleSurvivesInitializationAndLastsFullDuration()
	{
		timers.onConfirmedUse(PotionEffect.SILK_DRESSING, START);
		timers.onConfirmedUse(PotionEffect.BLESSED_CRYSTAL_SCARAB, START);
		timers.tick(Map.of(), START);
		assertEquals(60, remaining(PotionEffect.SILK_DRESSING, 0), DELTA);
		assertEquals(24, remaining(PotionEffect.BLESSED_CRYSTAL_SCARAB, 0), DELTA);
		for (int tick = 1; tick < 40; tick++)
		{
			timers.tick(Map.of(), atTick(tick));
		}
		assertEquals(0.6, remaining(PotionEffect.BLESSED_CRYSTAL_SCARAB, 39), DELTA);
		timers.tick(Map.of(), atTick(40));
		assertTrue(timers.get(PotionEffect.BLESSED_CRYSTAL_SCARAB).isReady());
		assertFalse(timers.get(PotionEffect.BLESSED_CRYSTAL_SCARAB).isActive());
		assertTrue(timers.get(PotionEffect.SILK_DRESSING).isActive());
		for (int tick = 41; tick <= 100; tick++)
		{
			timers.tick(Map.of(), atTick(tick));
		}
		assertTrue(timers.get(PotionEffect.SILK_DRESSING).isReady());
		assertEquals(0, timers.get(PotionEffect.SILK_DRESSING).getFinishedAgeSeconds(atTick(100)), DELTA);
	}

	@Test
	public void explicitInitializationAlsoRetainsPendingConfirmation()
	{
		timers.onConfirmedUse(PotionEffect.SILK_DRESSING, START);
		timers.initialize(Map.of(), START);
		assertEquals(60, remaining(PotionEffect.SILK_DRESSING, 0), DELTA);
	}

	@Test
	public void redosingChatOnlyEffectRestartsOnlyItsOwnDuration()
	{
		timers.onConfirmedUse(PotionEffect.SILK_DRESSING, START);
		timers.onConfirmedUse(PotionEffect.BLESSED_CRYSTAL_SCARAB, START);
		timers.tick(Map.of(), START);
		for (int tick = 1; tick < 20; tick++)
		{
			timers.tick(Map.of(), atTick(tick));
		}
		timers.onConfirmedUse(PotionEffect.BLESSED_CRYSTAL_SCARAB, atTick(20));
		timers.tick(Map.of(), atTick(20));
		assertEquals(24, remaining(PotionEffect.BLESSED_CRYSTAL_SCARAB, 20), DELTA);
		assertEquals(48, remaining(PotionEffect.SILK_DRESSING, 20), DELTA);
		for (int tick = 21; tick <= 60; tick++)
		{
			timers.tick(Map.of(), atTick(tick));
		}
		assertTrue(timers.get(PotionEffect.BLESSED_CRYSTAL_SCARAB).isReady());
		assertTrue(timers.get(PotionEffect.SILK_DRESSING).isActive());
	}

	@Test
	public void deathClearsConfirmedEffectsAndTheirPendingMessages()
	{
		timers.onConfirmedUse(PotionEffect.SILK_DRESSING, START);
		timers.onConfirmedUse(PotionEffect.BLESSED_CRYSTAL_SCARAB, START);
		timers.clearOnDeath();
		timers.tick(Map.of(PotionEffect.SURGE, 50), START);
		assertUnavailable(PotionEffect.SILK_DRESSING);
		assertUnavailable(PotionEffect.BLESSED_CRYSTAL_SCARAB);
		assertTrue(timers.get(PotionEffect.SURGE).isActive());
		timers.onConfirmedUse(PotionEffect.SILK_DRESSING, atTick(1));
		timers.tick(Map.of(PotionEffect.SURGE, 50), atTick(1));
		timers.clearOnDeath();
		assertUnavailable(PotionEffect.SILK_DRESSING);
		assertTrue(timers.get(PotionEffect.SURGE).isActive());
	}

	@Test
	public void lifecycleClearDoesNotResurrectAConfirmedEffectOnTheNextSample()
	{
		timers.onConfirmedUse(PotionEffect.SILK_DRESSING, START);
		timers.clear();
		timers.tick(Map.of(), atTick(1));
		assertUnavailable(PotionEffect.SILK_DRESSING);
		assertUnavailable(PotionEffect.BLESSED_CRYSTAL_SCARAB);
	}

	private void assertUnavailable(PotionEffect effect)
	{
		assertFalse(effect.name(), timers.get(effect).isActive());
		assertFalse(effect.name(), timers.get(effect).isReady());
	}

	private double remaining(PotionEffect effect, int tick)
	{
		return timers.get(effect).getRemainingSeconds(atTick(tick));
	}

	private static Map<PotionEffect, Integer> poison(int raw)
	{
		return Map.of(PotionEffect.ANTIPOISON, raw, PotionEffect.ANTIVENOM, raw);
	}

	private static long atTick(int tick)
	{
		return START + tick * Cooldown.TICK_NANOS;
	}

	private static Client client(Map<Integer, Integer> varbits, Map<Integer, Integer> varps)
	{
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				if (method.getName().equals("getVarbitValue") && args.length == 1)
				{
					return varbits.getOrDefault(args[0], 0);
				}
				if (method.getName().equals("getVarpValue"))
				{
					return varps.getOrDefault(args[0], 0);
				}
				throw new UnsupportedOperationException(method.getName());
			});
	}
}

package com.cooldownoverlays;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class BoostDecayClockTest
{
	private final BoostDecayClock clock = new BoostDecayClock();

	@Test
	public void phaseIsUnknownUntilANaturalDecayIsObserved()
	{
		assertEquals(-1, clock.ticksToNextDecay(50, false));
		assertEquals(-1, clock.ticksToNextDecay(75, true));
	}

	@Test
	public void ordinaryBoostsDecayAfterOneHundredTicks()
	{
		clock.observeDecay(20);
		assertEquals(100, clock.ticksToNextDecay(20, false));
		assertEquals(75, clock.ticksToNextDecay(45, false));
		assertEquals(1, clock.ticksToNextDecay(119, false));
		clock.observeDecay(120);
		assertEquals(100, clock.ticksToNextDecay(120, false));
	}

	@Test
	public void aMissedDecreaseInvalidatesThePhaseRatherThanExtendingIt()
	{
		clock.observeDecay(20);
		assertEquals(1, clock.ticksToNextDecay(119, false));
		assertEquals(-1, clock.ticksToNextDecay(120, false));
		assertEquals(-1, clock.ticksToNextDecay(121, false));
		assertEquals(-1, clock.ticksToNextDecay(146, true));
		clock.observeDecay(150);
		assertEquals(100, clock.ticksToNextDecay(150, false));
	}

	@Test
	public void skippingTheFirstCycleDoesNotFabricatePreserveExtensions()
	{
		clock.observeDecay(20);
		assertEquals(-1, clock.ticksToNextDecay(146, true));
	}

	@Test
	public void preserveActiveEarlyExtendsTheCycleToOneHundredFiftyTicks()
	{
		clock.observeDecay(20);
		assertEquals(150, clock.ticksToNextDecay(20, true));
		assertEquals(75, clock.ticksToNextDecay(95, true));
		assertEquals(50, clock.ticksToNextDecay(120, true));
		assertEquals(1, clock.ticksToNextDecay(169, true));
		assertEquals(-1, clock.ticksToNextDecay(170, true));
	}

	@Test
	public void preserveCanQualifyBeforeTheSeventyFifthTick()
	{
		clock.observeDecay(0);
		assertEquals(77, clock.ticksToNextDecay(23, false));
		assertEquals(76, clock.ticksToNextDecay(74, true));
		assertEquals(50, clock.ticksToNextDecay(100, true));
	}

	@Test
	public void preserveActivatedTooLateDoesNotExtendTheCurrentCycle()
	{
		clock.observeDecay(0);
		assertEquals(26, clock.ticksToNextDecay(74, false));
		assertEquals(25, clock.ticksToNextDecay(75, true));
		assertEquals(1, clock.ticksToNextDecay(99, true));
		assertEquals(-1, clock.ticksToNextDecay(100, true));
	}

	@Test
	public void turningPreserveOffBeforeTheFirstExtensionRestoresTheNormalDeadline()
	{
		clock.observeDecay(0);
		assertEquals(150, clock.ticksToNextDecay(0, true));
		assertEquals(20, clock.ticksToNextDecay(80, false));
		assertEquals(19, clock.ticksToNextDecay(81, true));
		assertEquals(-1, clock.ticksToNextDecay(100, true));
	}

	@Test
	public void turningPreserveOffAfterOneHundredTicksKeepsTheFirstExtension()
	{
		clock.observeDecay(0);
		assertEquals(150, clock.ticksToNextDecay(0, true));
		assertEquals(50, clock.ticksToNextDecay(100, true));
		assertEquals(24, clock.ticksToNextDecay(101, false));
		assertEquals(15, clock.ticksToNextDecay(110, true));
		assertEquals(1, clock.ticksToNextDecay(124, false));
		assertEquals(-1, clock.ticksToNextDecay(125, false));
	}

	@Test
	public void turningPreserveOffAfterTheSecondExtensionKeepsItsDeadline()
	{
		clock.observeDecay(0);
		assertEquals(150, clock.ticksToNextDecay(0, true));
		assertEquals(25, clock.ticksToNextDecay(125, true));
		assertEquals(24, clock.ticksToNextDecay(126, false));
		assertEquals(1, clock.ticksToNextDecay(149, false));
		assertEquals(-1, clock.ticksToNextDecay(150, false));
	}

	@Test
	public void duplicateDecayEventsDoNotResetPreserveQualification()
	{
		clock.observeDecay(0);
		assertEquals(150, clock.ticksToNextDecay(0, true));
		clock.observeDecay(0);
		assertEquals(75, clock.ticksToNextDecay(75, true));
	}

	@Test
	public void aNewDecayStartsNewPreserveQualification()
	{
		clock.observeDecay(0);
		assertEquals(150, clock.ticksToNextDecay(0, true));
		clock.observeDecay(150);
		assertEquals(100, clock.ticksToNextDecay(150, false));
		assertEquals(25, clock.ticksToNextDecay(225, true));
	}

	@Test
	public void clearingForLogoutOrHopForgetsThePhase()
	{
		clock.observeDecay(20);
		assertEquals(150, clock.ticksToNextDecay(20, true));
		clock.clear();
		assertEquals(-1, clock.ticksToNextDecay(21, true));
		clock.observeDecay(1);
		assertEquals(100, clock.ticksToNextDecay(1, false));
	}

	@Test
	public void backwardsTicksInvalidateThePhase()
	{
		clock.observeDecay(20);
		assertEquals(-1, clock.ticksToNextDecay(19, false));
		assertEquals(-1, clock.ticksToNextDecay(20, true));
	}
}

package com.cooldownoverlays;

import java.lang.reflect.Proxy;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class BoostPotionClientTest
{
	private final Map<Integer, Integer> varbits = new HashMap<>();
	private final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
	private final BoostPotionTimers timers = new BoostPotionTimers();
	private final CooldownOverlaysConfig config = new CooldownOverlaysConfig()
	{
		@Override public int attackThreshold() { return 103; }
		@Override public int strengthThreshold() { return 103; }
		@Override public int defenceThreshold() { return 103; }
		@Override public int rangedThreshold() { return 103; }
		@Override public int magicThreshold() { return 103; }
	};
	private int tick;
	private final Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
		new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			switch (method.getName())
			{
				case "getRealSkillLevel": return 99;
				case "getBoostedSkillLevel": return levels.getOrDefault(args[0], 99);
				case "getTickCount": return tick;
				case "getVarbitValue": return varbits.getOrDefault(args[0], 0);
				default: throw new UnsupportedOperationException(method.getName());
			}
		});

	@Test
	public void divineProtectionSuppressesOnlyTheRelevantSkills()
	{
		varbits.put(VarbitID.DIVINEATTACK_POTION_TIME, 500);
		timers.tick(client, config, 0);
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isReady());
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isActive());
		assertTrue(timers.get(BoostPotion.SUPER_STRENGTH).isReady());
		assertTrue(timers.get(BoostPotion.SUPER_COMBAT).isReady());
		varbits.put(VarbitID.DIVINEATTACK_POTION_TIME, 0);
		tick++;
		timers.tick(client, config, tick * Cooldown.TICK_NANOS);
		assertTrue(timers.get(BoostPotion.SUPER_ATTACK).isReady());
	}

	@Test
	public void compoundDivineProtectionCoversEveryAffectedStat()
	{
		varbits.put(VarbitID.DIVINECOMBAT_POTION_TIME, 500);
		varbits.put(VarbitID.DIVINEBASTION_POTION_TIME, 500);
		varbits.put(VarbitID.DIVINEBATTLEMAGE_POTION_TIME, 500);
		timers.tick(client, config, 0);
		for (BoostPotion potion : BoostPotion.values())
		{
			assertFalse(potion.name(), timers.get(potion).isReady());
			assertFalse(potion.name(), timers.get(potion).isActive());
		}
	}

	@Test
	public void raidOverloadProtectionRequiresBeingInsideChambers()
	{
		varbits.put(VarbitID.RAIDS_OVERLOAD_TIMER, 20);
		varbits.put(VarbitID.RAIDS_CLIENT_INDUNGEON, 1);
		timers.tick(client, config, 0);
		assertAllUnavailable();
		varbits.put(VarbitID.RAIDS_CLIENT_INDUNGEON, 0);
		tick++;
		timers.tick(client, config, tick * Cooldown.TICK_NANOS);
		assertTrue(timers.get(BoostPotion.SUPER_COMBAT).isReady());
	}

	@Test
	public void saltsNightmareZoneAndBlightedOverloadsMaintainCombatBoosts()
	{
		int[] effects = {VarbitID.TOA_MIDRAIDLOOT_STATS_TIMER,
			VarbitID.NZONE_OVERLOAD_POTION_EFFECTS, VarbitID.DEADMAN_OVERLOAD_POTION_EFFECTS};
		for (int effect : effects)
		{
			timers.clear();
			varbits.clear();
			varbits.put(effect, 1);
			timers.tick(client, config, 0);
			assertAllUnavailable();
		}
	}

	@Test
	public void heartSizedMagicBoostDoesNotAdvertiseANormalMagicDose()
	{
		varbits.put(VarbitID.IMBUED_HEART_TIMER, 50);
		levels.put(Skill.MAGIC, 112);
		timers.tick(client, config, 0);
		assertFalse(timers.get(BoostPotion.MAGIC).isReady());
		assertFalse(timers.get(BoostPotion.MAGIC).isActive());
		assertTrue(timers.get(BoostPotion.SUPER_ATTACK).isReady());
	}

	@Test
	public void preserveVarbitExtendsLearnedDecayEstimate()
	{
		varbits.put(VarbitID.PRAYER_PRESERVE, 1);
		levels.put(Skill.ATTACK, 119);
		timers.tick(client, config, 0);
		levels.put(Skill.ATTACK, 118);
		tick = 100;
		timers.tick(client, config, tick * Cooldown.TICK_NANOS);
		assertEquals(1440, timers.get(BoostPotion.SUPER_ATTACK)
			.getRemainingSeconds(tick * Cooldown.TICK_NANOS), 0.00001);
	}

	@Test
	public void unconfiguredTargetsDoNotGeneratePotionPrompts()
	{
		timers.tick(client, new CooldownOverlaysConfig() {}, 0);
		assertAllUnavailable();
	}

	@Test
	public void clientReadsIndependentAbsoluteTargetsForEverySkill()
	{
		CooldownOverlaysConfig targets = new CooldownOverlaysConfig()
		{
			@Override public int attackThreshold() { return 107; }
			@Override public int strengthThreshold() { return 110; }
			@Override public int defenceThreshold() { return 105; }
			@Override public int rangedThreshold() { return 108; }
			@Override public int magicThreshold() { return 102; }
		};
		levels.put(Skill.ATTACK, 107);
		levels.put(Skill.STRENGTH, 110);
		levels.put(Skill.DEFENCE, 105);
		levels.put(Skill.RANGED, 108);
		levels.put(Skill.MAGIC, 102);
		timers.tick(client, targets, 0);
		for (BoostPotion potion : BoostPotion.values())
		{
			assertFalse(potion.name(), timers.get(potion).isReady());
			assertTrue(potion.name(), timers.get(potion).isActive());
		}

		levels.replaceAll((skill, level) -> level - 1);
		tick = 100;
		timers.tick(client, targets, tick * Cooldown.TICK_NANOS);
		for (BoostPotion potion : BoostPotion.values())
		{
			assertTrue(potion.name(), timers.get(potion).isReady());
			assertFalse(potion.name(), timers.get(potion).isActive());
		}
	}

	@Test
	public void moonlightDefenceMarkerDoesNotHideUsefulOrdinaryPotions()
	{
		varbits.put(VarbitID.MOONLIGHT_POTION_TIME, 499);
		varbits.put(VarbitID.DIVINEDEFENCE_POTION_TIME, 500);
		timers.tick(client, config, 0);
		assertTrue(timers.get(BoostPotion.SUPER_DEFENCE).isReady());
		assertTrue(timers.get(BoostPotion.DEFENCE).isReady());

		varbits.put(VarbitID.DIVINEDEFENCE_POTION_TIME, 700);
		timers.tick(client, config, Cooldown.TICK_NANOS);
		assertFalse(timers.get(BoostPotion.SUPER_DEFENCE).isReady());
		assertFalse(timers.get(BoostPotion.SUPER_DEFENCE).isActive());
	}

	@Test
	public void naturalDefenceDecayUnderMoonlightCanTeachTheSharedPhase()
	{
		varbits.put(VarbitID.MOONLIGHT_POTION_TIME, 500);
		varbits.put(VarbitID.DIVINEDEFENCE_POTION_TIME, 500);
		levels.put(Skill.DEFENCE, 119);
		timers.tick(client, config, 0);
		levels.put(Skill.DEFENCE, 118);
		tick = 100;
		timers.tick(client, config, tick * Cooldown.TICK_NANOS);
		assertTrue(timers.get(BoostPotion.SUPER_DEFENCE).isKnown());
		assertEquals(960, timers.get(BoostPotion.SUPER_DEFENCE)
			.getRemainingSeconds(tick * Cooldown.TICK_NANOS), 0.00001);
	}

	private void assertAllUnavailable()
	{
		for (BoostPotion potion : BoostPotion.values())
		{
			assertFalse(potion.name(), timers.get(potion).isReady());
			assertFalse(potion.name(), timers.get(potion).isActive());
		}
	}
}

package com.cooldownoverlays;

import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BoostPotionTest
{
	@Test
	public void meleePotionsKeepOneFamilyAcrossEveryDoseAndMix()
	{
		assertFamily(BoostPotion.ATTACK,
			ItemID._4DOSE1ATTACK, ItemID._3DOSE1ATTACK, ItemID._2DOSE1ATTACK, ItemID._1DOSE1ATTACK,
			ItemID.BRUTAL_2DOSE1ATTACK, ItemID.BRUTAL_1DOSE1ATTACK);
		assertFamily(BoostPotion.STRENGTH,
			ItemID.STRENGTH4, ItemID._3DOSE1STRENGTH, ItemID._2DOSE1STRENGTH, ItemID._1DOSE1STRENGTH,
			ItemID.BRUTAL_2DOSE1STRENGTH, ItemID.BRUTAL_1DOSE1STRENGTH);
		assertFamily(BoostPotion.DEFENCE,
			ItemID._4DOSE1DEFENSE, ItemID._3DOSE1DEFENSE, ItemID._2DOSE1DEFENSE, ItemID._1DOSE1DEFENSE,
			ItemID.BRUTAL_2DOSE1DEFENSE, ItemID.BRUTAL_1DOSE1DEFENSE);
		assertFamily(BoostPotion.SUPER_ATTACK,
			ItemID._4DOSE2ATTACK, ItemID._3DOSE2ATTACK, ItemID._2DOSE2ATTACK, ItemID._1DOSE2ATTACK,
			ItemID.BRUTAL_2DOSE2ATTACK, ItemID.BRUTAL_1DOSE2ATTACK);
		assertFamily(BoostPotion.SUPER_STRENGTH,
			ItemID._4DOSE2STRENGTH, ItemID._3DOSE2STRENGTH, ItemID._2DOSE2STRENGTH, ItemID._1DOSE2STRENGTH,
			ItemID.BRUTAL_2DOSE2STRENGTH, ItemID.BRUTAL_1DOSE2STRENGTH);
		assertFamily(BoostPotion.SUPER_DEFENCE,
			ItemID._4DOSE2DEFENSE, ItemID._3DOSE2DEFENSE, ItemID._2DOSE2DEFENSE, ItemID._1DOSE2DEFENSE,
			ItemID.BRUTAL_2DOSE2DEFENSE, ItemID.BRUTAL_1DOSE2DEFENSE);
	}

	@Test
	public void combinedPotionsRetainAllBeneficialSkills()
	{
		assertFamily(BoostPotion.COMBAT,
			ItemID._4DOSECOMBAT, ItemID._3DOSECOMBAT, ItemID._2DOSECOMBAT, ItemID._1DOSECOMBAT,
			ItemID.BRUTAL_2DOSECOMBAT, ItemID.BRUTAL_1DOSECOMBAT,
			ItemID._4DOSECOMBAT_DEADMAN_STARTER, ItemID._3DOSECOMBAT_DEADMAN_STARTER,
			ItemID._2DOSECOMBAT_DEADMAN_STARTER, ItemID._1DOSECOMBAT_DEADMAN_STARTER);
		assertFamily(BoostPotion.SUPER_COMBAT,
			ItemID._4DOSE2COMBAT, ItemID._3DOSE2COMBAT, ItemID._2DOSE2COMBAT, ItemID._1DOSE2COMBAT);
		assertFamily(BoostPotion.BASTION,
			ItemID._4DOSEBASTION, ItemID._3DOSEBASTION, ItemID._2DOSEBASTION, ItemID._1DOSEBASTION);
		assertFamily(BoostPotion.BATTLEMAGE,
			ItemID._4DOSEBATTLEMAGE, ItemID._3DOSEBATTLEMAGE, ItemID._2DOSEBATTLEMAGE, ItemID._1DOSEBATTLEMAGE);
		assertArrayEquals(new Skill[]{Skill.ATTACK, Skill.STRENGTH}, BoostPotion.COMBAT.getSkills());
		assertArrayEquals(new Skill[]{Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE}, BoostPotion.SUPER_COMBAT.getSkills());
		assertArrayEquals(new Skill[]{Skill.RANGED, Skill.DEFENCE}, BoostPotion.BASTION.getSkills());
		assertArrayEquals(new Skill[]{Skill.MAGIC, Skill.DEFENCE}, BoostPotion.BATTLEMAGE.getSkills());
	}

	@Test
	public void rangedAndMagicIncludeMixesAndRangedBountySupplies()
	{
		assertFamily(BoostPotion.RANGING,
			ItemID._4DOSERANGERSPOTION, ItemID._3DOSERANGERSPOTION,
			ItemID._2DOSERANGERSPOTION, ItemID._1DOSERANGERSPOTION,
			ItemID.BRUTAL_2DOSERANGERSPOTION, ItemID.BRUTAL_1DOSERANGERSPOTION,
			ItemID.BR_4DOSERANGERSPOTION, ItemID.BR_3DOSERANGERSPOTION,
			ItemID.BR_2DOSERANGERSPOTION, ItemID.BR_1DOSERANGERSPOTION);
		assertFamily(BoostPotion.MAGIC,
			ItemID._4DOSE1MAGIC, ItemID._3DOSE1MAGIC, ItemID._2DOSE1MAGIC, ItemID._1DOSE1MAGIC,
			ItemID.BRUTAL_2DOSE1MAGIC, ItemID.BRUTAL_1DOSE1MAGIC);
	}

	@Test
	public void meleeBoostCapsUseFlooredBaseLevelAndPotionStrength()
	{
		assertEquals(111, BoostPotion.ATTACK.getBoostedLevel(Skill.ATTACK, 99));
		assertEquals(111, BoostPotion.STRENGTH.getBoostedLevel(Skill.STRENGTH, 99));
		assertEquals(111, BoostPotion.DEFENCE.getBoostedLevel(Skill.DEFENCE, 99));
		assertEquals(118, BoostPotion.SUPER_ATTACK.getBoostedLevel(Skill.ATTACK, 99));
		assertEquals(118, BoostPotion.SUPER_STRENGTH.getBoostedLevel(Skill.STRENGTH, 99));
		assertEquals(118, BoostPotion.SUPER_DEFENCE.getBoostedLevel(Skill.DEFENCE, 99));
		assertEquals(23, BoostPotion.ATTACK.getBoostedLevel(Skill.ATTACK, 19));
		assertEquals(25, BoostPotion.ATTACK.getBoostedLevel(Skill.ATTACK, 20));
		assertEquals(26, BoostPotion.SUPER_ATTACK.getBoostedLevel(Skill.ATTACK, 19));
		assertEquals(28, BoostPotion.SUPER_ATTACK.getBoostedLevel(Skill.ATTACK, 20));
	}

	@Test
	public void combinedPotionsApplyTheirDifferentStatCaps()
	{
		assertEquals(111, BoostPotion.COMBAT.getBoostedLevel(Skill.ATTACK, 99));
		assertEquals(111, BoostPotion.COMBAT.getBoostedLevel(Skill.STRENGTH, 99));
		assertEquals(99, BoostPotion.COMBAT.getBoostedLevel(Skill.DEFENCE, 99));
		for (Skill skill : BoostPotion.SUPER_COMBAT.getSkills())
		{
			assertEquals(118, BoostPotion.SUPER_COMBAT.getBoostedLevel(skill, 99));
		}
		assertEquals(112, BoostPotion.BASTION.getBoostedLevel(Skill.RANGED, 99));
		assertEquals(118, BoostPotion.BASTION.getBoostedLevel(Skill.DEFENCE, 99));
		assertEquals(103, BoostPotion.BATTLEMAGE.getBoostedLevel(Skill.MAGIC, 99));
		assertEquals(118, BoostPotion.BATTLEMAGE.getBoostedLevel(Skill.DEFENCE, 99));
	}

	@Test
	public void magicIsFlatWhileRangingDependsOnBaseLevel()
	{
		assertEquals(5, BoostPotion.MAGIC.getBoostedLevel(Skill.MAGIC, 1));
		assertEquals(103, BoostPotion.MAGIC.getBoostedLevel(Skill.MAGIC, 99));
		assertEquals(5, BoostPotion.RANGING.getBoostedLevel(Skill.RANGED, 1));
		assertEquals(112, BoostPotion.RANGING.getBoostedLevel(Skill.RANGED, 99));
		assertEquals(90, BoostPotion.RANGING.getBoostedLevel(Skill.MAGIC, 90));
	}

	@Test
	public void skillArrayCannotMutatePotionDefinitions()
	{
		Skill[] skills = BoostPotion.ATTACK.getSkills();
		skills[0] = Skill.DEFENCE;
		assertArrayEquals(new Skill[]{Skill.ATTACK}, BoostPotion.ATTACK.getSkills());
	}

	@Test
	public void notesPlaceholdersDivinesRaidsAndRestoresHaveNoOrdinaryBoostOverlay()
	{
		int[] unsupported = {
			-1, ItemID.Cert._4DOSE2ATTACK, ItemID.Placeholder._4DOSE2ATTACK,
			ItemID.Cert.STRENGTH4, ItemID.Placeholder.STRENGTH4,
			ItemID._4DOSEDIVINECOMBAT, ItemID._4DOSEDIVINEBATTLEMAGE,
			ItemID.RAIDS_VIAL_OVERLOAD_STRONG_4, ItemID.TOA_SUPPLY_STATS_2,
			ItemID._4DOSESTAMINA, ItemID._4DOSESTATRESTORE, ItemID._4DOSEPOTIONOFSARADOMIN,
			ItemID._4DOSEPOTIONOFZAMORAK
		};
		for (int itemId : unsupported)
		{
			assertNull("ordinary boost for " + itemId, BoostPotion.forItem(itemId));
		}
	}

	@Test
	public void everyFamilyIsEnabledByDefaultAndHasItsOwnSetting()
	{
		CooldownOverlaysConfig defaults = new CooldownOverlaysConfig() {};
		CooldownOverlaysConfig selected = new CooldownOverlaysConfig()
		{
			@Override
			public boolean attackPotion()
			{
				return false;
			}

			@Override
			public boolean superDefencePotion()
			{
				return false;
			}

			@Override
			public boolean bastionPotion()
			{
				return false;
			}
		};
		for (BoostPotion potion : BoostPotion.values())
		{
			assertTrue(potion.name(), potion.isEnabled(defaults));
			if (potion == BoostPotion.ATTACK || potion == BoostPotion.SUPER_DEFENCE || potion == BoostPotion.BASTION)
			{
				assertFalse(potion.name(), potion.isEnabled(selected));
			}
			else
			{
				assertTrue(potion.name(), potion.isEnabled(selected));
			}
		}
	}

	private static void assertFamily(BoostPotion expected, int... itemIds)
	{
		for (int itemId : itemIds)
		{
			assertEquals("boost family for " + itemId, expected, BoostPotion.forItem(itemId));
			assertNull("separate fixed effect for " + itemId, PotionItems.getFamily(itemId));
		}
	}
}

package com.cooldownoverlays;

import java.util.EnumMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class BoostPotionTimersTest
{
	private static final double DELTA = 0.000001;
	private static final long START = 1_000_000_000L;
	private final BoostPotionTimers timers = new BoostPotionTimers();
	private final Map<Skill, Integer> base = levels(99, 99, 99, 99, 99);

	@Test
	public void unboostedSkillIsReadyOnInitialSample()
	{
		tick(0, levels(99, 99, 99, 99, 99), Set.of(), false, 103);

		assertTrue(timers.get(BoostPotion.SUPER_ATTACK).isReady());
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isActive());
		assertEquals(0, timers.get(BoostPotion.SUPER_ATTACK).getFinishedAgeSeconds(atTick(0)), DELTA);
	}

	@Test
	public void boostedInitialSampleWaitsForObservedDecayPhase()
	{
		tick(0, levels(118, 99, 99, 99, 99), Set.of(), false, 103);

		assertTrue(timers.get(BoostPotion.SUPER_ATTACK).isActive());
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isKnown());
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isReady());
	}

	@Test
	public void observedSingleLevelDecayPredictsTimeToThreshold()
	{
		tick(99, levels(119, 99, 99, 99, 99), Set.of(), false, 103);
		tick(100, levels(118, 99, 99, 99, 99), Set.of(), false, 103);

		Cooldown cooldown = timers.get(BoostPotion.SUPER_ATTACK);
		assertTrue(cooldown.isKnown());
		assertFalse(cooldown.isReady());
		// Level 118 drops below 103 after sixteen further one-minute decays.
		assertEquals(960, cooldown.getRemainingSeconds(atTick(100)), DELTA);
	}

	@Test
	public void drinkingAgainRetainsTheSharedDecayPhase()
	{
		tick(99, levels(109, 99, 99, 99, 99), Set.of(), false, 103);
		tick(100, levels(108, 99, 99, 99, 99), Set.of(), false, 103);
		tick(110, levels(118, 99, 99, 99, 99), Set.of(), false, 103);

		assertTrue(timers.get(BoostPotion.SUPER_ATTACK).isKnown());
		// Next decay is tick 200, rather than one minute after drinking at tick 110.
		assertEquals(954, timers.get(BoostPotion.SUPER_ATTACK).getRemainingSeconds(atTick(110)), DELTA);
	}

	@Test
	public void preserveUsesNinetySecondDecayIntervals()
	{
		tick(99, levels(119, 99, 99, 99, 99), Set.of(), true, 103);
		tick(100, levels(118, 99, 99, 99, 99), Set.of(), true, 103);

		assertTrue(timers.get(BoostPotion.SUPER_ATTACK).isKnown());
		assertEquals(1440, timers.get(BoostPotion.SUPER_ATTACK).getRemainingSeconds(atTick(100)), DELTA);
	}

	@Test
	public void thresholdChangesRecalculateTimerAndReadiness()
	{
		tick(99, levels(109, 99, 99, 99, 99), Set.of(), false, 103);
		tick(100, levels(108, 99, 99, 99, 99), Set.of(), false, 103);
		assertEquals(360, timers.get(BoostPotion.SUPER_ATTACK).getRemainingSeconds(atTick(100)), DELTA);

		tick(101, levels(108, 99, 99, 99, 99), Set.of(), false, 108);
		assertEquals(59.4, timers.get(BoostPotion.SUPER_ATTACK).getRemainingSeconds(atTick(101)), DELTA);
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isReady());

		tick(102, levels(108, 99, 99, 99, 99), Set.of(), false, 109);
		assertTrue(timers.get(BoostPotion.SUPER_ATTACK).isReady());
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isActive());
	}

	@Test
	public void combinedPotionUsesFirstBeneficialSkillToReachThreshold()
	{
		tick(99, levels(104, 118, 118, 99, 99), Set.of(), false, 103);
		tick(100, levels(103, 118, 118, 99, 99), Set.of(), false, 103);

		assertEquals(60, timers.get(BoostPotion.SUPER_COMBAT).getRemainingSeconds(atTick(100)), DELTA);
		assertFalse(timers.get(BoostPotion.SUPER_COMBAT).isReady());
		tick(199, levels(103, 118, 118, 99, 99), Set.of(), false, 103);
		assertFalse(timers.get(BoostPotion.SUPER_COMBAT).isReady());

		tick(200, levels(102, 117, 117, 99, 99), Set.of(), false, 103);
		assertTrue(timers.get(BoostPotion.SUPER_COMBAT).isReady());
	}

	@Test
	public void protectedStatsCannotTriggerReadyAnimation()
	{
		tick(0, levels(99, 118, 118, 99, 99), Set.of(Skill.ATTACK), false, 103);

		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isReady());
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isActive());
		assertFalse(timers.get(BoostPotion.SUPER_COMBAT).isReady());
		assertTrue(timers.get(BoostPotion.SUPER_COMBAT).isActive());

		tick(1, levels(99, 99, 99, 99, 99), Set.of(Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE), false, 103);
		assertFalse(timers.get(BoostPotion.SUPER_COMBAT).isReady());
		assertFalse(timers.get(BoostPotion.SUPER_COMBAT).isActive());
	}

	@Test
	public void protectedSingleLevelDropDoesNotTeachNaturalDecayPhase()
	{
		tick(99, levels(119, 118, 99, 99, 99), Set.of(Skill.ATTACK), false, 103);
		tick(100, levels(118, 118, 99, 99, 99), Set.of(Skill.ATTACK), false, 103);

		assertFalse(timers.get(BoostPotion.SUPER_STRENGTH).isKnown());
		assertTrue(timers.get(BoostPotion.SUPER_STRENGTH).isActive());
	}

	@Test
	public void bulkDrainAndDoseIncreasesDoNotTeachDecayPhase()
	{
		tick(99, levels(118, 99, 99, 99, 99), Set.of(), false, 103);
		tick(100, levels(110, 99, 99, 99, 99), Set.of(), false, 103);
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isKnown());

		tick(101, levels(118, 99, 99, 99, 99), Set.of(), false, 103);
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isKnown());
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isReady());
	}

	@Test
	public void realLevelChangeDoesNotTeachDecayPhase()
	{
		base.put(Skill.ATTACK, 98);
		tick(99, levels(118, 99, 99, 99, 99), Set.of(), false, 103);
		base.put(Skill.ATTACK, 99);
		tick(100, levels(117, 99, 99, 99, 99), Set.of(), false, 103);

		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isKnown());
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isReady());
	}

	@Test
	public void countdownCannotDeclareReadyBeforeObservedThresholdCrossing()
	{
		tick(99, levels(104, 99, 99, 99, 99), Set.of(), false, 103);
		tick(100, levels(103, 99, 99, 99, 99), Set.of(), false, 103);
		tick(201, levels(103, 99, 99, 99, 99), Set.of(), false, 103);

		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isReady());
		assertTrue(timers.get(BoostPotion.SUPER_ATTACK).isActive());

		tick(202, levels(102, 99, 99, 99, 99), Set.of(), false, 103);
		assertTrue(timers.get(BoostPotion.SUPER_ATTACK).isReady());
	}

	@Test
	public void highThresholdCannotAdvertiseAUsefulDoseAtFullPotionCap()
	{
		tick(0, levels(118, 99, 99, 99, 99), Set.of(), false, 130);
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isReady());

		tick(1, levels(117, 99, 99, 99, 99), Set.of(), false, 130);
		assertTrue(timers.get(BoostPotion.SUPER_ATTACK).isReady());

		tick(2, levels(118, 99, 99, 99, 99), Set.of(), false, 130);
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isReady());
		assertEquals(-1, timers.get(BoostPotion.SUPER_ATTACK).getFinishedAgeSeconds(atTick(2)), DELTA);
	}

	@Test
	public void missingSkillValuesAreUnavailableRatherThanReady()
	{
		timers.tick(0, Map.of(), Map.of(), Set.of(), false, thresholds(103), atTick(0));
		for (BoostPotion potion : BoostPotion.values())
		{
			assertFalse(potion.name(), timers.get(potion).isReady());
			assertFalse(potion.name(), timers.get(potion).isActive());
		}
	}

	@Test
	public void missingBoostedSampleCannotAnimateAsAnUnboostedSkill()
	{
		timers.tick(0, base, Map.of(), Set.of(), false, thresholds(103), atTick(0));
		for (BoostPotion potion : BoostPotion.values())
		{
			assertFalse(potion.name(), timers.get(potion).isReady());
			assertFalse(potion.name(), timers.get(potion).isActive());
		}
	}

	@Test
	public void clearDiscardsReadinessAndLearnedPhase()
	{
		tick(99, levels(119, 99, 99, 99, 99), Set.of(), false, 103);
		tick(100, levels(118, 99, 99, 99, 99), Set.of(), false, 103);
		assertTrue(timers.get(BoostPotion.SUPER_ATTACK).isKnown());
		assertTrue(timers.get(BoostPotion.MAGIC).isReady());

		timers.clear();
		for (BoostPotion potion : BoostPotion.values())
		{
			assertFalse(potion.name(), timers.get(potion).isReady());
			assertFalse(potion.name(), timers.get(potion).isActive());
		}

		tick(101, levels(118, 99, 99, 99, 99), Set.of(), false, 103);
		assertTrue(timers.get(BoostPotion.SUPER_ATTACK).isActive());
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isKnown());
	}

	@Test
	public void strengthBelow110WaitsAt110AndAnimatesAt109()
	{
		Map<Skill, Integer> targets = Map.of(Skill.STRENGTH, 110);
		timers.tick(99, base, levels(99, 111, 99, 99, 99), Set.of(), false, targets, atTick(99));
		timers.tick(100, base, levels(99, 110, 99, 99, 99), Set.of(), false, targets, atTick(100));
		Cooldown cooldown = timers.get(BoostPotion.SUPER_STRENGTH);
		assertFalse(cooldown.isReady());
		assertEquals(60, cooldown.getRemainingSeconds(atTick(100)), DELTA);

		timers.tick(200, base, levels(99, 109, 99, 99, 99), Set.of(), false, targets, atTick(200));
		assertTrue(cooldown.isReady());
		assertFalse(cooldown.isActive());
		assertTrue(timers.get(BoostPotion.SUPER_COMBAT).isReady());
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isReady());
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isActive());
	}

	@Test
	public void eachSkillUsesItsOwnAbsoluteTarget()
	{
		Map<Skill, Integer> targets = levels(0, 110, 0, 105, 102);
		timers.tick(99, base, levels(99, 111, 99, 104, 102), Set.of(), false, targets, atTick(99));
		timers.tick(100, base, levels(99, 110, 99, 104, 102), Set.of(), false, targets, atTick(100));

		assertEquals(60, timers.get(BoostPotion.SUPER_COMBAT).getRemainingSeconds(atTick(100)), DELTA);
		assertTrue(timers.get(BoostPotion.RANGING).isReady());
		assertTrue(timers.get(BoostPotion.BASTION).isReady());
		assertFalse(timers.get(BoostPotion.MAGIC).isReady());
		assertEquals(60, timers.get(BoostPotion.BATTLEMAGE).getRemainingSeconds(atTick(100)), DELTA);
		assertFalse(timers.get(BoostPotion.DEFENCE).isActive());
		assertFalse(timers.get(BoostPotion.DEFENCE).isReady());
	}

	@Test
	public void disablingTargetClearsBothCountdownAndReadiness()
	{
		timers.tick(0, base, levels(99, 109, 99, 99, 99), Set.of(), false,
			Map.of(Skill.STRENGTH, 110), atTick(0));
		assertTrue(timers.get(BoostPotion.SUPER_STRENGTH).isReady());
		timers.tick(1, base, levels(99, 109, 99, 99, 99), Set.of(), false,
			Map.of(Skill.STRENGTH, 109), atTick(1));
		assertTrue(timers.get(BoostPotion.SUPER_STRENGTH).isActive());
		assertFalse(timers.get(BoostPotion.SUPER_STRENGTH).isReady());

		timers.tick(2, base, levels(99, 109, 99, 99, 99), Set.of(), false,
			Map.of(Skill.STRENGTH, 0), atTick(2));
		for (BoostPotion potion : BoostPotion.values())
		{
			assertFalse(potion.name(), timers.get(potion).isReady());
			assertFalse(potion.name(), timers.get(potion).isActive());
		}
	}

	@Test
	public void belowBaseTargetWaitsForAnActualDrainInsteadOfPredictingOne()
	{
		Map<Skill, Integer> targets = Map.of(Skill.STRENGTH, 90);
		// Attack teaches the shared phase even though its target is disabled.
		timers.tick(99, base, levels(111, 95, 99, 99, 99), Set.of(), false, targets, atTick(99));
		timers.tick(100, base, levels(110, 95, 99, 99, 99), Set.of(), false, targets, atTick(100));
		assertFalse(timers.get(BoostPotion.SUPER_STRENGTH).isActive());
		assertFalse(timers.get(BoostPotion.SUPER_STRENGTH).isReady());

		timers.tick(101, base, levels(110, 89, 99, 99, 99), Set.of(), false, targets, atTick(101));
		assertTrue(timers.get(BoostPotion.SUPER_STRENGTH).isReady());
		timers.tick(102, base, levels(110, 90, 99, 99, 99), Set.of(), false, targets, atTick(102));
		assertFalse(timers.get(BoostPotion.SUPER_STRENGTH).isReady());
		assertFalse(timers.get(BoostPotion.SUPER_STRENGTH).isActive());
	}

	@Test
	public void thresholdAtBaseCannotNaturallyCrossButOneAboveCan()
	{
		Map<Skill, Integer> targets = levels(99, 100, 0, 0, 0);
		timers.tick(99, base, levels(101, 101, 99, 99, 99), Set.of(), false, targets, atTick(99));
		timers.tick(100, base, levels(100, 100, 99, 99, 99), Set.of(), false, targets, atTick(100));
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isActive());
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isReady());
		assertEquals(60, timers.get(BoostPotion.SUPER_STRENGTH).getRemainingSeconds(atTick(100)), DELTA);
		timers.tick(200, base, levels(99, 99, 99, 99, 99), Set.of(), false, targets, atTick(200));
		assertFalse(timers.get(BoostPotion.SUPER_ATTACK).isReady());
		assertTrue(timers.get(BoostPotion.SUPER_STRENGTH).isReady());
	}

	@Test
	public void absoluteTargetDoesNotMoveWhenBaseLevelChanges()
	{
		base.put(Skill.STRENGTH, 90);
		Map<Skill, Integer> targets = Map.of(Skill.STRENGTH, 105);
		timers.tick(0, base, levels(99, 104, 99, 99, 99), Set.of(), false, targets, atTick(0));
		assertTrue(timers.get(BoostPotion.SUPER_STRENGTH).isReady());
		base.put(Skill.STRENGTH, 91);
		timers.tick(1, base, levels(99, 104, 99, 99, 99), Set.of(), false, targets, atTick(1));
		assertTrue(timers.get(BoostPotion.SUPER_STRENGTH).isReady());
		timers.tick(2, base, levels(99, 105, 99, 99, 99), Set.of(), false, targets, atTick(2));
		assertFalse(timers.get(BoostPotion.SUPER_STRENGTH).isReady());
	}

	@Test
	public void absoluteTargetStillRequiresAPotionThatCanImproveTheSkill()
	{
		Map<Skill, Integer> targets = Map.of(Skill.STRENGTH, 110);
		timers.tick(0, base, levels(99, 112, 99, 99, 99), Set.of(), false, targets, atTick(0));
		assertFalse(timers.get(BoostPotion.STRENGTH).isReady());
		timers.tick(1, base, levels(99, 110, 99, 99, 99), Set.of(), false, targets, atTick(1));
		assertFalse(timers.get(BoostPotion.STRENGTH).isReady());
		timers.tick(2, base, levels(99, 109, 99, 99, 99), Set.of(), false, targets, atTick(2));
		assertTrue(timers.get(BoostPotion.STRENGTH).isReady());
		assertTrue(timers.get(BoostPotion.SUPER_STRENGTH).isReady());
	}

	private void tick(int tick, Map<Skill, Integer> boosted, Set<Skill> protectedSkills, boolean preserve, int threshold)
	{
		timers.tick(tick, base, boosted, protectedSkills, preserve, thresholds(threshold), atTick(tick));
	}

	private static Map<Skill, Integer> thresholds(int level)
	{
		return levels(level, level, level, level, level);
	}

	private static Map<Skill, Integer> levels(int attack, int strength, int defence, int ranged, int magic)
	{
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		levels.put(Skill.ATTACK, attack);
		levels.put(Skill.STRENGTH, strength);
		levels.put(Skill.DEFENCE, defence);
		levels.put(Skill.RANGED, ranged);
		levels.put(Skill.MAGIC, magic);
		return levels;
	}

	private static long atTick(int tick)
	{
		return START + tick * Cooldown.TICK_NANOS;
	}
}

package com.cooldownoverlays;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Exercises the plugin's event boundaries without a RuneLite client or event bus. */
public class ConsumableIntegrationTest
{
	private static final String SILK_MESSAGE = "You quickly apply the dressing to your wounds.";
	private static final String SCARAB_MESSAGE = "You crack the crystal in your hand.";
	private final CooldownOverlaysPlugin plugin = new CooldownOverlaysPlugin();
	private final PotionTimers timers = new PotionTimers();
	private GameState gameState = GameState.LOGGED_IN;
	private Player localPlayer = player();
	private final Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
		new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			switch (method.getName())
			{
				case "getGameState": return gameState;
				case "getLocalPlayer": return localPlayer;
				default: throw new UnsupportedOperationException(method.getName());
			}
		});

	@Before
	public void injectEventDependencies() throws Exception
	{
		inject("client", client);
		inject("potionTimers", timers);
		inject("tracker", new CooldownTracker());
		inject("boostPotionTimers", new BoostPotionTimers());
		inject("running", true);
	}

	@Test
	public void exactGameAndSpamMessagesStartOnlyTheMatchingConsumableTimer()
	{
		for (ChatMessageType type : new ChatMessageType[]{ChatMessageType.GAMEMESSAGE, ChatMessageType.SPAM})
		{
			timers.clear();
			plugin.onChatMessage(chat(type, SILK_MESSAGE));
			assertRunning(PotionEffect.SILK_DRESSING, 100);
			assertFalse(timers.get(PotionEffect.BLESSED_CRYSTAL_SCARAB).isActive());
			timers.clear();
			plugin.onChatMessage(chat(type, SCARAB_MESSAGE));
			assertRunning(PotionEffect.BLESSED_CRYSTAL_SCARAB, 40);
			assertFalse(timers.get(PotionEffect.SILK_DRESSING).isActive());
		}
	}

	@Test
	public void gameTextTagsDoNotPreventConfirmedUses()
	{
		plugin.onChatMessage(chat(ChatMessageType.GAMEMESSAGE, "<col=ff0000>" + SILK_MESSAGE + "</col>"));
		plugin.onChatMessage(chat(ChatMessageType.SPAM, "<col=00ff00>" + SCARAB_MESSAGE + "</col>"));
		assertRunning(PotionEffect.SILK_DRESSING, 100);
		assertRunning(PotionEffect.BLESSED_CRYSTAL_SCARAB, 40);
	}

	@Test
	public void otherChatChannelsCannotSpoofConsumableUses()
	{
		for (ChatMessageType type : ChatMessageType.values())
		{
			if (type == ChatMessageType.GAMEMESSAGE || type == ChatMessageType.SPAM)
			{
				continue;
			}
			plugin.onChatMessage(chat(type, SILK_MESSAGE));
			plugin.onChatMessage(chat(type, SCARAB_MESSAGE));
			assertBothCleared();
		}
	}

	@Test
	public void similarOrUnsuccessfulMessagesDoNotStartTimers()
	{
		String[] messages = {
			"You cannot apply the dressing to your wounds.",
			"You cannot crack the crystal in your hand.",
			"Someone says: " + SILK_MESSAGE,
			SCARAB_MESSAGE + " Again.",
			"You quickly apply the dressing to your wounds",
			"You crack the crystal in your hand",
			"you quickly apply the dressing to your wounds.",
			"you crack the crystal in your hand."
		};
		for (String message : messages)
		{
			plugin.onChatMessage(chat(ChatMessageType.GAMEMESSAGE, message));
			assertBothCleared();
		}
	}

	@Test
	public void messagesOutsideLoggedInStateCannotStartTimers()
	{
		for (GameState state : GameState.values())
		{
			if (state == GameState.LOGGED_IN)
			{
				continue;
			}
			gameState = state;
			plugin.onChatMessage(chat(ChatMessageType.GAMEMESSAGE, SILK_MESSAGE));
			plugin.onChatMessage(chat(ChatMessageType.SPAM, SCARAB_MESSAGE));
			assertBothCleared();
		}
	}

	@Test
	public void stoppedPluginIgnoresConfirmedUseMessages() throws Exception
	{
		inject("running", false);
		plugin.onChatMessage(chat(ChatMessageType.GAMEMESSAGE, SILK_MESSAGE));
		plugin.onChatMessage(chat(ChatMessageType.SPAM, SCARAB_MESSAGE));
		assertBothCleared();
	}

	@Test
	public void localPlayerDeathClearsBothChatTrackedEffects()
	{
		startBoth();
		plugin.onActorDeath(new ActorDeath(localPlayer));
		assertBothCleared();
	}

	@Test
	public void anotherPlayerDeathPreservesBothChatTrackedEffects()
	{
		startBoth();
		plugin.onActorDeath(new ActorDeath(player()));
		assertRunning(PotionEffect.SILK_DRESSING, 100);
		assertRunning(PotionEffect.BLESSED_CRYSTAL_SCARAB, 40);
	}

	@Test
	public void missingLocalPlayerDoesNotMistakeNullActorForLocalDeath()
	{
		startBoth();
		localPlayer = null;
		plugin.onActorDeath(new ActorDeath(null));
		assertRunning(PotionEffect.SILK_DRESSING, 100);
		assertRunning(PotionEffect.BLESSED_CRYSTAL_SCARAB, 40);
	}

	@Test
	public void stoppedPluginIgnoresDeathEvents() throws Exception
	{
		startBoth();
		inject("running", false);
		plugin.onActorDeath(new ActorDeath(localPlayer));
		assertRunning(PotionEffect.SILK_DRESSING, 100);
		assertRunning(PotionEffect.BLESSED_CRYSTAL_SCARAB, 40);
	}

	@Test
	public void sessionTransitionsDiscardDurationsThatCannotBeRehydrated()
	{
		GameState[] transitions = {GameState.LOGIN_SCREEN, GameState.HOPPING,
			GameState.CONNECTION_LOST, GameState.LOGGING_IN};
		for (GameState transition : transitions)
		{
			startBoth();
			GameStateChanged event = new GameStateChanged();
			event.setGameState(transition);
			plugin.onGameStateChanged(event);
			assertBothCleared();
		}
	}

	private void startBoth()
	{
		plugin.onChatMessage(chat(ChatMessageType.GAMEMESSAGE, SILK_MESSAGE));
		plugin.onChatMessage(chat(ChatMessageType.GAMEMESSAGE, SCARAB_MESSAGE));
		assertRunning(PotionEffect.SILK_DRESSING, 100);
		assertRunning(PotionEffect.BLESSED_CRYSTAL_SCARAB, 40);
	}

	private void assertRunning(PotionEffect effect, int ticks)
	{
		Cooldown cooldown = timers.get(effect);
		assertTrue(effect.name(), cooldown.isActive());
		assertTrue(effect.name(), cooldown.isKnown());
		assertFalse(effect.name(), cooldown.isReady());
		assertEquals(effect.name(), ticks, cooldown.getTotalTicks());
	}

	private void assertBothCleared()
	{
		for (PotionEffect effect : new PotionEffect[]{PotionEffect.SILK_DRESSING, PotionEffect.BLESSED_CRYSTAL_SCARAB})
		{
			assertFalse(effect.name(), timers.get(effect).isActive());
			assertFalse(effect.name(), timers.get(effect).isReady());
		}
	}

	private static ChatMessage chat(ChatMessageType type, String message)
	{
		ChatMessage event = new ChatMessage();
		event.setType(type);
		event.setMessage(message);
		return event;
	}

	private void inject(String name, Object value) throws Exception
	{
		Field field = CooldownOverlaysPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(plugin, value);
	}

	private static Player player()
	{
		return (Player) Proxy.newProxyInstance(Player.class.getClassLoader(), new Class<?>[]{Player.class},
			(proxy, method, args) ->
			{
				throw new UnsupportedOperationException(method.getName());
			});
	}
}

package com.cooldownoverlays;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CooldownAnimationTest
{
	private static final long SECOND = 1_000_000_000L;
	private static final Rectangle ICON = new Rectangle(4, 4, 32, 32);

	@Test
	public void readyBorderMovesWithoutObscuringTheCenterOfAnIcon()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.setReady(0);
		BufferedImage first = render(cooldown, 0, true, AnimationMode.PERMANENT);
		BufferedImage later = render(cooldown, SECOND / 3, true, AnimationMode.PERMANENT);
		assertTrue(visiblePixels(first) > 0);
		assertTrue(imagesDiffer(first, later));
		assertEquals(0, first.getRGB(20, 20));
		assertEquals(0, later.getRGB(20, 20));
	}

	@Test
	public void animationsAreOptionalAndDisabledByDefault()
	{
		CooldownOverlaysConfig defaults = new CooldownOverlaysConfig() { };
		assertFalse(defaults.animateWhenReady());
		Cooldown cooldown = new Cooldown();
		cooldown.start(100, 100, 0);
		assertEquals(0, visiblePixels(render(cooldown, 0, false, AnimationMode.TIMED)));
		cooldown.finish(0);
		assertEquals(0, visiblePixels(render(cooldown, 0, false, AnimationMode.TIMED)));
		assertEquals(0, visiblePixels(render(cooldown, 0, false, AnimationMode.PERMANENT)));
	}

	@Test
	public void activeTimersNeverAnimateEvenWhenTheReadyAnimationIsEnabled()
	{
		Cooldown cooldown = new Cooldown();
		for (AnimationMode mode : AnimationMode.values())
		{
			cooldown.start(100, 100, 0);
			assertEquals(0, visiblePixels(render(cooldown, 0, true, mode)));
			cooldown.startUnknown(0);
			BufferedImage enabled = render(cooldown, SECOND, true, mode);
			BufferedImage disabled = render(cooldown, SECOND, false, mode);
			assertFalse(imagesDiffer(enabled, disabled));
		}
	}

	@Test
	public void timedReadyAnimationMovesThenExpiresAtTheConfiguredDuration()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(1, 1, 0);
		cooldown.finish(0);
		BufferedImage first = render(cooldown, 0, true, AnimationMode.TIMED);
		BufferedImage later = render(cooldown, SECOND / 3, true, AnimationMode.TIMED);
		assertTrue(visiblePixels(first) > 0);
		assertTrue(imagesDiffer(first, later));
		assertEquals(0, first.getRGB(20, 20));
		assertEquals(0, visiblePixels(render(cooldown, 3 * SECOND, true, AnimationMode.TIMED)));
		assertTrue(visiblePixels(render(cooldown, 4 * SECOND, config(true, AnimationMode.TIMED, 5))) > 0);
		assertEquals(0, visiblePixels(render(cooldown, 5 * SECOND, config(true, AnimationMode.TIMED, 5))));
	}

	@Test
	public void permanentAnimationRemainsVisibleUntilTheItemIsUsed()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.setReady(0);
		assertTrue(visiblePixels(render(cooldown, 60 * SECOND, true, AnimationMode.PERMANENT)) > 0);
		cooldown.start(100, 100, 60 * SECOND);
		assertEquals(0, visiblePixels(render(cooldown, 60 * SECOND, true, AnimationMode.PERMANENT)));
	}

	@Test
	public void initialConfirmedReadySampleCanAnimateButUninitializedStateCannot()
	{
		Cooldown cooldown = new Cooldown();
		assertEquals(0, visiblePixels(render(cooldown, 0, true, AnimationMode.PERMANENT)));
		cooldown.finish(SECOND);
		assertTrue(cooldown.isReady());
		assertTrue(visiblePixels(render(cooldown, SECOND, true, AnimationMode.TIMED)) > 0);
	}

	@Test
	public void readySamplesDoNotRetriggerOrExtendTheAnimation()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(1, 1, 0);
		cooldown.finish(0);
		cooldown.finish(2 * SECOND);
		assertEquals(2, cooldown.getFinishedAgeSeconds(2 * SECOND), 0.00001);
		assertEquals(0, visiblePixels(render(cooldown, 3 * SECOND, true, AnimationMode.TIMED)));
	}

	@Test
	public void lifecycleClearAndANewDoseCancelTheReadyAnimation()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.finish(0);
		cooldown.clear();
		assertFalse(cooldown.isReady());
		assertEquals(0, visiblePixels(render(cooldown, SECOND, true, AnimationMode.TIMED)));
		cooldown.start(1, 1, SECOND);
		cooldown.finish(SECOND);
		cooldown.start(100, 100, 2 * SECOND);
		assertFalse(cooldown.isReady());
		assertEquals(-1, cooldown.getFinishedAgeSeconds(2 * SECOND), 0);
		assertEquals(0, visiblePixels(render(cooldown, 2 * SECOND, true, AnimationMode.TIMED)));
		cooldown.finish(3 * SECOND);
		assertTrue(visiblePixels(render(cooldown, 3 * SECOND, true, AnimationMode.TIMED)) > 0);
	}

	@Test
	public void readyAnimationRespectsTheParentClipAndGraphicsState()
	{
		BufferedImage image = new BufferedImage(40, 40, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		Rectangle clip = new Rectangle(4, 4, 16, 32);
		Cooldown cooldown = new Cooldown();
		cooldown.start(1, 1, 0);
		cooldown.finish(0);
		try
		{
			graphics.setClip(clip);
			graphics.setColor(Color.MAGENTA);
			new CooldownRenderer(config(true, AnimationMode.PERMANENT, 3)).render(graphics, ICON, cooldown, 0);
			assertEquals(clip, graphics.getClipBounds());
			assertEquals(Color.MAGENTA, graphics.getColor());
			assertTrue(visiblePixels(image) > 0);
			for (int x = 20; x < 40; x++)
			{
				for (int y = 0; y < 40; y++)
				{
					assertEquals(0, image.getRGB(x, y));
				}
			}
		}
		finally
		{
			graphics.dispose();
		}
	}

	private static BufferedImage render(Cooldown cooldown, long nowNanos, boolean enabled, AnimationMode mode)
	{
		return render(cooldown, nowNanos, config(enabled, mode, 3));
	}

	private static BufferedImage render(Cooldown cooldown, long nowNanos, CooldownOverlaysConfig config)
	{
		BufferedImage image = new BufferedImage(40, 40, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			new CooldownRenderer(config).render(graphics, ICON, cooldown, nowNanos);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static CooldownOverlaysConfig config(boolean enabled, AnimationMode mode, int duration)
	{
		return new CooldownOverlaysConfig()
		{
			@Override
			public BorderStyle animationBorderStyle()
			{
				return BorderStyle.INVENTORY_SLOT;
			}

			@Override
			public DisplayMode displayMode()
			{
				return DisplayMode.CIRCLE;
			}

			@Override
			public int circleOpacity()
			{
				return 0;
			}

			@Override
			public boolean animateWhenReady()
			{
				return enabled;
			}

			@Override
			public AnimationMode animationMode()
			{
				return mode;
			}

			@Override
			public int animationDuration()
			{
				return duration;
			}
		};
	}

	private static int visiblePixels(BufferedImage image)
	{
		int count = 0;
		for (int x = 0; x < image.getWidth(); x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				if ((image.getRGB(x, y) >>> 24) > 0)
				{
					count++;
				}
			}
		}
		return count;
	}

	private static boolean imagesDiffer(BufferedImage first, BufferedImage second)
	{
		for (int x = 0; x < first.getWidth(); x++)
		{
			for (int y = 0; y < first.getHeight(); y++)
			{
				if (first.getRGB(x, y) != second.getRGB(x, y))
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.cooldownoverlays;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CooldownBorderTest
{
	private static final long SECOND = 1_000_000_000L;
	private static final Rectangle ICON = new Rectangle(16, 16, 36, 32);
	private static final Shape BOTTLE = ItemOutlineCache.trace(bottleSprite());

	@Test
	public void itemBorderFollowsBottleNeckAndBodyWithoutFillingItsCenterOrCorners()
	{
		BufferedImage image = render(ready(), 0, ICON, BOTTLE,
			config(BorderStyle.ITEM_OUTLINE, 2, AnimationMode.PERMANENT, 3, DisplayMode.BOTH));

		assertTrue("The narrow neck has its own contour", alpha(image, 16 + 15, 16 + 8) > 0);
		assertTrue("The wider body has its own contour", alpha(image, 16 + 7, 16 + 22) > 0);
		assertEquals("No bounding-box edge beside the neck", 0, alpha(image, 16 + 7, 16 + 8));
		assertEquals("The bottle center remains unobscured", 0, alpha(image, 16 + 18, 16 + 22));
		assertEquals(0, alpha(image, 16 + 1, 16 + 1));
		assertEquals(0, alpha(image, 16 + 34, 16 + 1));
		assertEquals(0, alpha(image, 16 + 1, 16 + 31));
		assertEquals(0, alpha(image, 16 + 34, 16 + 31));
	}

	@Test
	public void widerSettingDrawsAMeasurablyThickerContour()
	{
		BufferedImage thin = render(ready(), 0, ICON, BOTTLE,
			config(BorderStyle.ITEM_OUTLINE, 1, AnimationMode.PERMANENT, 3, DisplayMode.BOTH));
		BufferedImage thick = render(ready(), 0, ICON, BOTTLE,
			config(BorderStyle.ITEM_OUTLINE, 6, AnimationMode.PERMANENT, 3, DisplayMode.BOTH));

		assertTrue(visiblePixels(thin) > 0);
		assertTrue("Six-pixel strokes cover more pixels than one-pixel strokes",
			visiblePixels(thick) > visiblePixels(thin));
		assertEquals("One-pixel border leaves this distant neck pixel clear", 0,
			alpha(thin, 16 + 11, 16 + 8));
		assertTrue("Six-pixel border reaches farther out from the same neck",
			alpha(thick, 16 + 11, 16 + 8) > 0);
		assertEquals("Width changes do not fill the bottle", 0,
			alpha(thick, 16 + 18, 16 + 22));
	}

	@Test
	public void nativeItemGeometryIsTranslatedWithoutResizingToWidgetBounds()
	{
		CooldownOverlaysConfig config = config(BorderStyle.ITEM_OUTLINE, 2,
			AnimationMode.PERMANENT, 3, DisplayMode.BOTH);
		BufferedImage original = render(ready(), 0, ICON, BOTTLE, config);
		BufferedImage larger = render(ready(), 0, new Rectangle(16, 16, 60, 48), BOTTLE, config);
		BufferedImage smaller = render(ready(), 0, new Rectangle(16, 16, 10, 8), BOTTLE, config);
		assertImagesEqual(original, larger);
		assertImagesEqual(original, smaller);

		BufferedImage moved = render(ready(), 0, new Rectangle(23, 27, 36, 32), BOTTLE, config);
		for (int x = 0; x < 80; x++)
		{
			for (int y = 0; y < 80; y++)
			{
				assertEquals("The same local contour moves with the item's origin",
					original.getRGB(x, y), moved.getRGB(x + 7, y + 11));
			}
		}
	}

	@Test
	public void outlineRespectsInheritedClipAndPreservesCallerGraphicsState()
	{
		BufferedImage image = new BufferedImage(120, 120, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		AffineTransform transform = new AffineTransform();
		transform.translate(4, 3);
		transform.scale(1.5, 1.5);
		Rectangle clip = new Rectangle(0, 0, 26, 70);
		BasicStroke stroke = new BasicStroke(4);
		AlphaComposite composite = AlphaComposite.SrcOver.derive(0.7f);
		Font font = new Font(Font.MONOSPACED, Font.PLAIN, 9);
		try
		{
			graphics.setTransform(transform);
			graphics.setClip(clip);
			graphics.setStroke(stroke);
			graphics.setComposite(composite);
			graphics.setColor(Color.MAGENTA);
			graphics.setFont(font);
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
			new CooldownRenderer(config(BorderStyle.ITEM_OUTLINE, 6,
				AnimationMode.PERMANENT, 3, DisplayMode.BOTH)).render(graphics, ICON, ready(), 0, BOTTLE);

			assertEquals(transform, graphics.getTransform());
			assertEquals(clip, graphics.getClipBounds());
			assertEquals(stroke, graphics.getStroke());
			assertEquals(composite, graphics.getComposite());
			assertEquals(Color.MAGENTA, graphics.getColor());
			assertEquals(font, graphics.getFont());
			assertEquals(RenderingHints.VALUE_ANTIALIAS_OFF,
				graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING));
			assertTrue(visiblePixels(image) > 0);
			// The clip's transformed right edge is 4 + 26 * 1.5 = 43.
			for (int x = 43; x < image.getWidth(); x++)
			{
				for (int y = 0; y < image.getHeight(); y++)
				{
					assertEquals("The parent clip remains authoritative", 0, alpha(image, x, y));
				}
			}
		}
		finally
		{
			graphics.dispose();
		}
	}

	@Test
	public void silhouetteHaloMayExtendOutsideSpriteBoundsWithinTheParentClip()
	{
		BufferedImage sprite = new BufferedImage(20, 24, BufferedImage.TYPE_INT_ARGB);
		Graphics2D spriteGraphics = sprite.createGraphics();
		try
		{
			spriteGraphics.setColor(Color.WHITE);
			spriteGraphics.fillRect(0, 5, 10, 14);
		}
		finally
		{
			spriteGraphics.dispose();
		}
		BufferedImage image = new BufferedImage(64, 64, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setClip(new Rectangle(21, 20, 30, 35));
			new CooldownRenderer(config(BorderStyle.ITEM_OUTLINE, 6,
				AnimationMode.PERMANENT, 3, DisplayMode.BOTH)).render(graphics,
				new Rectangle(24, 24, 20, 24), ready(), 0, ItemOutlineCache.trace(sprite));
		}
		finally
		{
			graphics.dispose();
		}
		assertTrue("The contour stroke is not cut off by its source pixel box", alpha(image, 22, 35) > 0);
		assertEquals("The same halo remains clipped by the parent widget", 0, alpha(image, 20, 35));
	}

	@Test
	public void outlineMovesWhileReadyAndHonorsPermanentAndTimedModes()
	{
		Cooldown cooldown = ready();
		CooldownOverlaysConfig timed = config(BorderStyle.ITEM_OUTLINE, 2,
			AnimationMode.TIMED, 3, DisplayMode.BOTH);
		BufferedImage first = render(cooldown, 0, ICON, BOTTLE, timed);
		BufferedImage later = render(cooldown, SECOND / 3, ICON, BOTTLE, timed);
		assertTrue(visiblePixels(first) > 0);
		assertTrue(visiblePixels(later) > 0);
		assertFalse("The activation border advances along the contour",
			Arrays.equals(pixels(first), pixels(later)));
		assertEquals(0, visiblePixels(render(cooldown, 3 * SECOND, ICON, BOTTLE, timed)));
		assertTrue(visiblePixels(render(cooldown, 4 * SECOND, ICON, BOTTLE,
			config(BorderStyle.ITEM_OUTLINE, 2, AnimationMode.TIMED, 5, DisplayMode.BOTH))) > 0);
		assertEquals(0, visiblePixels(render(cooldown, 5 * SECOND, ICON, BOTTLE,
			config(BorderStyle.ITEM_OUTLINE, 2, AnimationMode.TIMED, 5, DisplayMode.BOTH))));
		assertTrue(visiblePixels(render(cooldown, 60 * SECOND, ICON, BOTTLE,
			config(BorderStyle.ITEM_OUTLINE, 2, AnimationMode.PERMANENT, 3, DisplayMode.BOTH))) > 0);
	}

	@Test
	public void unavailableOutlineDoesNotSubstituteAnInventoryRectangle()
	{
		CooldownOverlaysConfig defaults = new CooldownOverlaysConfig()
		{
			@Override
			public boolean animateWhenReady()
			{
				return true;
			}
		};
		assertEquals(0, visiblePixels(render(ready(), 0, ICON, null, defaults)));
		BufferedImage image = new BufferedImage(96, 96, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			new CooldownRenderer(defaults).render(graphics, ICON, ready(), 0);
		}
		finally
		{
			graphics.dispose();
		}
		assertEquals("The legacy render overload also waits for an outline", 0, visiblePixels(image));
		assertTrue("An explicit inventory-slot choice needs no sprite",
			visiblePixels(render(ready(), 0, ICON, null,
				config(BorderStyle.INVENTORY_SLOT, 2, AnimationMode.PERMANENT, 3, DisplayMode.BOTH))) > 0);
	}

	@Test
	public void activeKnownAndUnknownTimersIgnoreReadyBorderStyleAndWidth()
	{
		for (DisplayMode mode : DisplayMode.values())
		{
			for (boolean known : new boolean[]{true, false})
			{
				Cooldown cooldown = new Cooldown();
				if (known)
				{
					cooldown.start(30, 60, 0);
				}
				else
				{
					cooldown.startUnknown(0);
				}
				BufferedImage outline = render(cooldown, 0, ICON, BOTTLE,
					config(BorderStyle.ITEM_OUTLINE, 1, AnimationMode.PERMANENT, 3, mode));
				BufferedImage wideOutline = render(cooldown, 0, ICON, BOTTLE,
					config(BorderStyle.ITEM_OUTLINE, 6, AnimationMode.TIMED, 3, mode));
				BufferedImage tile = render(cooldown, 0, ICON, BOTTLE,
					config(BorderStyle.INVENTORY_SLOT, 6, AnimationMode.PERMANENT, 3, mode));
				assertTrue("The active timer still renders", visiblePixels(outline) > 0);
				assertImagesEqual(outline, wideOutline);
				assertImagesEqual(outline, tile);
				if (!mode.usesItemFill())
				{
					assertImagesEqual(outline, render(cooldown, 0, ICON, null,
						config(BorderStyle.ITEM_OUTLINE, 1, AnimationMode.PERMANENT, 3, mode)));
				}
			}
		}
	}

	private static Cooldown ready()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.setReady(0);
		return cooldown;
	}

	private static BufferedImage bottleSprite()
	{
		BufferedImage sprite = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = sprite.createGraphics();
		try
		{
			graphics.setColor(Color.WHITE);
			graphics.fillRect(15, 3, 6, 11);
			graphics.fillRect(11, 13, 14, 3);
			graphics.fillRect(7, 16, 22, 12);
			graphics.fillRect(10, 28, 16, 2);
		}
		finally
		{
			graphics.dispose();
		}
		return sprite;
	}

	private static BufferedImage render(Cooldown cooldown, long nowNanos, Rectangle bounds,
		Shape outline, CooldownOverlaysConfig config)
	{
		BufferedImage image = new BufferedImage(96, 96, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			new CooldownRenderer(config).render(graphics, bounds, cooldown, nowNanos, outline);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static CooldownOverlaysConfig config(BorderStyle style, int width, AnimationMode animationMode,
		int duration, DisplayMode displayMode)
	{
		return new CooldownOverlaysConfig()
		{
			@Override
			public boolean animateWhenReady()
			{
				return true;
			}

			@Override
			public BorderStyle animationBorderStyle()
			{
				return style;
			}

			@Override
			public int animationBorderWidth()
			{
				return width;
			}

			@Override
			public AnimationMode animationMode()
			{
				return animationMode;
			}

			@Override
			public int animationDuration()
			{
				return duration;
			}

			@Override
			public DisplayMode displayMode()
			{
				return displayMode;
			}
		};
	}

	private static int alpha(BufferedImage image, int x, int y)
	{
		return image.getRGB(x, y) >>> 24;
	}

	private static int visiblePixels(BufferedImage image)
	{
		int count = 0;
		for (int pixel : pixels(image))
		{
			if ((pixel >>> 24) != 0)
			{
				count++;
			}
		}
		return count;
	}

	private static int[] pixels(BufferedImage image)
	{
		return image.getRGB(0, 0, image.getWidth(), image.getHeight(), null, 0, image.getWidth());
	}

	private static void assertImagesEqual(BufferedImage expected, BufferedImage actual)
	{
		assertArrayEquals(pixels(expected), pixels(actual));
	}
}

package com.cooldownoverlays;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class CooldownItemFillTest
{
	private static final Rectangle ICON = new Rectangle(4, 4, 36, 32);
	private static final BufferedImage SPRITE = sprite();
	private static final Shape SILHOUETTE = ItemOutlineCache.trace(SPRITE);

	@Test
	public void revealRisesThroughTheActualItemHeightAndLeavesHolesAndMarginsClear()
	{
		for (int ticks : new int[]{20, 15, 10, 5})
		{
			Cooldown cooldown = new Cooldown();
			cooldown.start(ticks, 20, 0);
			BufferedImage image = render(cooldown, DisplayMode.ITEM_FILL, SILHOUETTE, 60, 0);
			// The item occupies rows 4 through 23; tile padding is not progress.
			int boundary = 4 + ticks;
			for (int y = 0; y < SPRITE.getHeight(); y++)
			{
				for (int x = 0; x < SPRITE.getWidth(); x++)
				{
					boolean shaded = (SPRITE.getRGB(x, y) >>> 24) != 0 && y < boundary;
					assertEquals("Only unrevealed sprite pixels are shaded at " + ticks + " ticks",
						shaded ? 153 : 0, alpha(image, ICON.x + x, ICON.y + y));
				}
			}
		}
	}

	@Test
	public void revealedPixelsRetainTheirOriginalColoursAndBackgroundIsUntouched()
	{
		BufferedImage image = new BufferedImage(48, 44, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		Color background = new Color(72, 62, 49);
		Cooldown cooldown = new Cooldown();
		cooldown.start(10, 20, 0);
		try
		{
			graphics.setColor(background);
			graphics.fillRect(0, 0, image.getWidth(), image.getHeight());
			graphics.drawImage(SPRITE, ICON.x, ICON.y, null);
			new CooldownRenderer(config(DisplayMode.ITEM_FILL, 60))
				.render(graphics, ICON, cooldown, 0, SILHOUETTE);
		}
		finally
		{
			graphics.dispose();
		}
		assertEquals(SPRITE.getRGB(12, 21), image.getRGB(ICON.x + 12, ICON.y + 21));
		assertEquals(SPRITE.getRGB(25, 20), image.getRGB(ICON.x + 25, ICON.y + 20));
		assertTrue("The unrevealed top remains dimmed",
			image.getRGB(ICON.x + 15, ICON.y + 5) != SPRITE.getRGB(15, 5));
		assertEquals("Transparent holes keep their background", background.getRGB(),
			image.getRGB(ICON.x + 17, ICON.y + 13));
		assertEquals(background.getRGB(), image.getRGB(ICON.x + 2, ICON.y + 2));
	}

	@Test
	public void optionalTimerKeepsItsOriginalPositionOverTheFill()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(10, 20, 0);
		BufferedImage fill = render(cooldown, DisplayMode.ITEM_FILL, SILHOUETTE, 60, 0);
		BufferedImage combined = render(cooldown, DisplayMode.TIMER_AND_ITEM_FILL, SILHOUETTE, 60, 0);
		BufferedImage timer = render(cooldown, DisplayMode.TIMER, null, 60, 0);
		assertEquals(0, whitePixels(fill));
		assertTrue(whitePixels(combined) > 0);
		for (int y = 0; y < timer.getHeight(); y++)
		{
			for (int x = 0; x < timer.getWidth(); x++)
			{
				assertEquals("The fill's local translation must not move the text",
					timer.getRGB(x, y) == Color.WHITE.getRGB(),
					combined.getRGB(x, y) == Color.WHITE.getRGB());
			}
		}
	}

	@Test
	public void unknownFillRemainsStaticAndShowsAQuestionMarkInBothModes()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.startUnknown(0);
		for (DisplayMode mode : new DisplayMode[]{DisplayMode.ITEM_FILL, DisplayMode.TIMER_AND_ITEM_FILL})
		{
			BufferedImage initial = render(cooldown, mode, SILHOUETTE, 60, 0);
			BufferedImage later = render(cooldown, mode, SILHOUETTE, 60, 10_000_000_000L);
			assertTrue(whitePixels(initial) > 0);
			assertEquals(77, alpha(initial, ICON.x + 15, ICON.y + 5));
			assertEquals(77, alpha(initial, ICON.x + 9, ICON.y + 22));
			assertEquals(0, alpha(initial, ICON.x + 2, ICON.y + 2));
			assertImagesEqual(initial, later);
		}
	}

	@Test
	public void missingOrEmptySilhouettesDoNotFallBackToATileOrCircle()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(20, 20, 0);
		for (Shape shape : new Shape[]{null, new Rectangle()})
		{
			assertEquals(0, visiblePixels(render(cooldown, DisplayMode.ITEM_FILL, shape, 60, 0)));
			assertTrue(whitePixels(render(cooldown, DisplayMode.TIMER_AND_ITEM_FILL, shape, 60, 0)) > 0);
		}
		cooldown.startUnknown(0);
		assertTrue(whitePixels(render(cooldown, DisplayMode.ITEM_FILL, null, 60, 0)) > 0);
	}

	@Test
	public void opacityControlsOnlyTheUnrevealedPixels()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(10, 20, 0);
		for (int opacity : new int[]{-10, 0, 60, 100, 110})
		{
			BufferedImage image = render(cooldown, DisplayMode.ITEM_FILL, SILHOUETTE, opacity, 0);
			int alpha = (int) Math.round(Math.max(0, Math.min(100, opacity)) * 255 / 100.0);
			assertEquals(alpha, alpha(image, ICON.x + 15, ICON.y + 5));
			assertEquals(0, alpha(image, ICON.x + 12, ICON.y + 21));
		}
	}

	@Test
	public void readyAndClearedCooldownsHaveNoRemainingMask()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(20, 20, 0);
		cooldown.setReady(0);
		assertEquals(0, visiblePixels(render(cooldown, DisplayMode.ITEM_FILL, SILHOUETTE, 60, 0)));
		cooldown.clear();
		assertEquals(0, visiblePixels(render(cooldown, DisplayMode.ITEM_FILL, SILHOUETTE, 60, 0)));
	}

	@Test
	public void fillPreservesGraphicsStateAndInheritedClipping()
	{
		BufferedImage image = new BufferedImage(48, 44, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		Rectangle clip = new Rectangle(4, 4, 16, 32);
		Font font = new Font(Font.MONOSPACED, Font.PLAIN, 9);
		AffineTransform transform = graphics.getTransform();
		Cooldown cooldown = new Cooldown();
		cooldown.start(20, 20, 0);
		try
		{
			graphics.setClip(clip);
			graphics.setFont(font);
			graphics.setColor(Color.MAGENTA);
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
			new CooldownRenderer(config(DisplayMode.TIMER_AND_ITEM_FILL, 60))
				.render(graphics, ICON, cooldown, 0, SILHOUETTE);
			assertEquals(transform, graphics.getTransform());
			assertEquals(clip, graphics.getClipBounds());
			assertEquals(font, graphics.getFont());
			assertEquals(Color.MAGENTA, graphics.getColor());
			assertEquals(RenderingHints.VALUE_ANTIALIAS_OFF,
				graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING));
			assertTrue(visiblePixels(image) > 0);
			for (int y = 0; y < image.getHeight(); y++)
			{
				for (int x = 0; x < image.getWidth(); x++)
				{
					if (!clip.contains(x, y))
					{
						assertEquals(0, alpha(image, x, y));
					}
				}
			}
		}
		finally
		{
			graphics.dispose();
		}
	}

	private static BufferedImage render(Cooldown cooldown, DisplayMode mode, Shape silhouette, int opacity, long now)
	{
		BufferedImage image = new BufferedImage(48, 44, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			new CooldownRenderer(config(mode, opacity)).render(graphics, ICON, cooldown, now, silhouette);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static CooldownOverlaysConfig config(DisplayMode mode, int opacity)
	{
		return new CooldownOverlaysConfig()
		{
			@Override public DisplayMode displayMode() { return mode; }
			@Override public int circleOpacity() { return opacity; }
		};
	}

	private static BufferedImage sprite()
	{
		BufferedImage image = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setColor(new Color(180, 120, 60));
		graphics.fillRect(12, 4, 10, 8);
		graphics.setColor(new Color(60, 190, 100));
		graphics.fillRect(8, 12, 20, 12);
		graphics.setColor(new Color(200, 230, 220));
		graphics.fillRect(12, 19, 3, 4);
		graphics.dispose();
		for (int y = 12; y < 16; y++)
		{
			for (int x = 16; x < 20; x++)
			{
				image.setRGB(x, y, 0);
			}
		}
		image.setRGB(30, 6, new Color(80, 160, 240).getRGB());
		return image;
	}

	private static int alpha(BufferedImage image, int x, int y)
	{
		return image.getRGB(x, y) >>> 24;
	}

	private static int whitePixels(BufferedImage image)
	{
		int count = 0;
		for (int pixel : image.getRGB(0, 0, image.getWidth(), image.getHeight(), null, 0, image.getWidth()))
		{
			if (pixel == Color.WHITE.getRGB()) count++;
		}
		return count;
	}

	private static int visiblePixels(BufferedImage image)
	{
		int count = 0;
		for (int pixel : image.getRGB(0, 0, image.getWidth(), image.getHeight(), null, 0, image.getWidth()))
		{
			if ((pixel >>> 24) != 0) count++;
		}
		return count;
	}

	private static void assertImagesEqual(BufferedImage expected, BufferedImage actual)
	{
		for (int y = 0; y < expected.getHeight(); y++)
		{
			for (int x = 0; x < expected.getWidth(); x++)
			{
				assertEquals(expected.getRGB(x, y), actual.getRGB(x, y));
			}
		}
	}
}

