package com.cooldownoverlays;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class CooldownRendererTest
{
	private static final Rectangle ICON = new Rectangle(4, 4, 32, 32);

	@Test
	public void timerRoundsUpAndFormatsMinuteBoundaries()
	{
		assertEquals("1", CooldownRenderer.formatSeconds(0.001));
		assertEquals("10", CooldownRenderer.formatSeconds(9.01));
		assertEquals("59", CooldownRenderer.formatSeconds(59));
		assertEquals("1:00", CooldownRenderer.formatSeconds(59.001));
		assertEquals("1:01", CooldownRenderer.formatSeconds(60.01));
		assertEquals("7:00", CooldownRenderer.formatSeconds(420));
	}

	@Test
	public void circleRevealsClockwiseFromTheTop()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(15, 20, 0);
		BufferedImage image = render(cooldown, DisplayMode.CIRCLE);

		assertEquals("The first quarter should already be clear", 0, alpha(image, 27, 12));
		assertEquals("The remaining three quarters stay shaded", 153, alpha(image, 12, 12));
		assertEquals(153, alpha(image, 27, 27));
		assertEquals(153, alpha(image, 12, 27));
		assertEquals("The circular sweep must leave the icon corners clear", 0, alpha(image, 4, 4));
	}

	@Test
	public void timerAndCircleCanBeSelectedIndependentlyOrTogether()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(15, 20, 0);
		BufferedImage timer = render(cooldown, DisplayMode.TIMER);
		BufferedImage circle = render(cooldown, DisplayMode.CIRCLE);
		BufferedImage both = render(cooldown, DisplayMode.BOTH);

		assertEquals(0, alpha(timer, 12, 12));
		assertEquals(153, alpha(circle, 12, 12));
		assertEquals(153, alpha(both, 12, 12));
		assertTrue("Timer mode should draw legible foreground text", whitePixels(timer) > 0);
		assertEquals("Circle mode should omit timer text", 0, whitePixels(circle));
		assertTrue("Both mode should retain timer text", whitePixels(both) > 0);
	}

	@Test
	public void unknownCooldownShowsADimStaticCircleAndQuestionMarkInLegacyModes()
	{
		Cooldown unknown = new Cooldown();
		unknown.startUnknown(0);
		for (DisplayMode mode : new DisplayMode[]{DisplayMode.TIMER, DisplayMode.CIRCLE, DisplayMode.BOTH})
		{
			BufferedImage image = render(unknown, mode);
			assertEquals(77, alpha(image, 12, 12));
			assertEquals(77, alpha(image, 27, 12));
			assertTrue(whitePixels(image) > 0);
		}
	}

	@Test
	public void clearedCooldownDrawsNothing()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(15, 20, 0);
		cooldown.clear();
		BufferedImage image = render(cooldown, DisplayMode.BOTH);
		assertEquals(0, visiblePixels(image));
	}

	@Test
	public void renderingRespectsExistingClipAndPreservesGraphicsState()
	{
		BufferedImage image = new BufferedImage(40, 40, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		Rectangle clip = new Rectangle(4, 4, 16, 32);
		Font font = new Font(Font.MONOSPACED, Font.PLAIN, 9);
		graphics.setClip(clip);
		graphics.setColor(Color.MAGENTA);
		graphics.setFont(font);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		Cooldown cooldown = new Cooldown();
		cooldown.start(20, 20, 0);
		try
		{
			new CooldownRenderer(config(DisplayMode.BOTH)).render(graphics, ICON, cooldown, 0);
			assertEquals(clip, graphics.getClipBounds());
			assertEquals(Color.MAGENTA, graphics.getColor());
			assertEquals(font, graphics.getFont());
			assertEquals(RenderingHints.VALUE_ANTIALIAS_OFF,
				graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING));
			assertTrue(alpha(image, 12, 12) > 0);
			for (int x = 20; x < image.getWidth(); x++)
			{
				for (int y = 0; y < image.getHeight(); y++)
				{
					assertEquals("No overlay pixel may escape the existing clip", 0, alpha(image, x, y));
				}
			}
		}
		finally
		{
			graphics.dispose();
		}
	}

	@Test
	public void invalidOrEmptyBoundsDrawNothing()
	{
		BufferedImage image = new BufferedImage(40, 40, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		Cooldown cooldown = new Cooldown();
		cooldown.start(20, 20, 0);
		try
		{
			new CooldownRenderer(config(DisplayMode.BOTH)).render(
				graphics, new Rectangle(4, 4, 0, 32), cooldown, 0);
		}
		finally
		{
			graphics.dispose();
		}
		assertEquals(0, visiblePixels(image));
	}

	private static BufferedImage render(Cooldown cooldown, DisplayMode mode)
	{
		BufferedImage image = new BufferedImage(40, 40, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			new CooldownRenderer(config(mode)).render(graphics, ICON, cooldown, 0);
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static CooldownOverlaysConfig config(DisplayMode mode)
	{
		return new CooldownOverlaysConfig()
		{
			@Override
			public DisplayMode displayMode()
			{
				return mode;
			}
		};
	}

	private static int alpha(BufferedImage image, int x, int y)
	{
		return image.getRGB(x, y) >>> 24;
	}

	private static int whitePixels(BufferedImage image)
	{
		int count = 0;
		for (int x = 0; x < image.getWidth(); x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				if (image.getRGB(x, y) == Color.WHITE.getRGB())
				{
					count++;
				}
			}
		}
		return count;
	}

	private static int visiblePixels(BufferedImage image)
	{
		int count = 0;
		for (int x = 0; x < image.getWidth(); x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				if (alpha(image, x, y) > 0)
				{
					count++;
				}
			}
		}
		return count;
	}
}

package com.cooldownoverlays;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CooldownTest
{
	private static final double DELTA = 0.000001;
	private static final long START = 1_000_000_000L;

	@Test
	public void countdownInterpolatesWithinOneTick()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(10, 20, START);

		assertEquals(6, cooldown.getRemainingSeconds(START), DELTA);
		assertEquals(5.7, cooldown.getRemainingSeconds(START + 300_000_000L), DELTA);
		assertEquals(0.475, cooldown.getRemainingFraction(START + 300_000_000L), DELTA);
	}

	@Test
	public void stalledClientCannotConsumeMoreThanOneTick()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(10, 10, START);

		assertEquals(5.4, cooldown.getRemainingSeconds(START + 60_000_000_000L), DELTA);
		assertTrue(cooldown.isActive());
	}

	@Test
	public void finalTickStaysActiveUntilServerClearsIt()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(1, 17, START);
		for (int tick = 1; tick <= 20; tick++)
		{
			cooldown.tick(START + tick * Cooldown.TICK_NANOS);
		}

		assertTrue(cooldown.isActive());
		assertTrue(cooldown.getRemainingSeconds(START + 100 * Cooldown.TICK_NANOS) > 0);
		cooldown.clear();
		assertFalse(cooldown.isActive());
		assertEquals(0, cooldown.getRemainingSeconds(START), DELTA);
		assertEquals(0, cooldown.getRemainingFraction(START), DELTA);
	}

	@Test
	public void unknownCountdownDoesNotInventTimeRemaining()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.startUnknown(START);
		cooldown.tick(START + Cooldown.TICK_NANOS);

		assertTrue(cooldown.isActive());
		assertFalse(cooldown.isKnown());
		assertEquals(0, cooldown.getRemainingSeconds(START), DELTA);
		assertEquals(1, cooldown.getRemainingFraction(START), DELTA);
	}

	@Test
	public void newServerSampleReplacesInterpolatedTime()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(10, 20, START);
		cooldown.start(8, 20, START + 3 * Cooldown.TICK_NANOS);

		assertEquals(4.8, cooldown.getRemainingSeconds(START + 3 * Cooldown.TICK_NANOS), DELTA);
		assertEquals(0.4, cooldown.getRemainingFraction(START + 3 * Cooldown.TICK_NANOS), DELTA);
	}

	@Test
	public void clockEarlierThanSampleDoesNotIncreaseCountdown()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.start(10, 10, START);

		assertEquals(6, cooldown.getRemainingSeconds(START - 1), DELTA);
		assertEquals(1, cooldown.getRemainingFraction(START - 1), DELTA);
	}

	@Test
	public void readyStateRequiresAConfirmedSampleAndRepeatedSamplesPreserveItsAge()
	{
		Cooldown cooldown = new Cooldown();
		assertFalse(cooldown.isActive());
		assertFalse(cooldown.isReady());
		assertEquals(-1, cooldown.getFinishedAgeSeconds(START), DELTA);
		cooldown.setReady(START);
		assertFalse(cooldown.isActive());
		assertTrue(cooldown.isReady());
		cooldown.finish(START + 2_000_000_000L);
		assertEquals(2, cooldown.getFinishedAgeSeconds(START + 2_000_000_000L), DELTA);
	}

	@Test
	public void activeUnknownAndClearedStatesAllResetReadiness()
	{
		Cooldown cooldown = new Cooldown();
		cooldown.finish(START);
		cooldown.start(10, 10, START);
		assertFalse(cooldown.isReady());
		assertEquals(-1, cooldown.getFinishedAgeSeconds(START), DELTA);
		cooldown.finish(START);
		cooldown.startUnknown(START);
		assertFalse(cooldown.isReady());
		cooldown.finish(START);
		cooldown.clear();
		assertFalse(cooldown.isReady());
		assertEquals(-1, cooldown.getFinishedAgeSeconds(START), DELTA);
	}
}

package com.cooldownoverlays;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CooldownTrackerTest
{
	private static final double DELTA = 0.000001;
	private static final long START = 1_000_000_000L;
	private final CooldownTracker tracker = new CooldownTracker();

	@Test
	public void readyServerStateHasNoCooldown()
	{
		tracker.tick(0, START);

		assertFalse(tracker.getHeart().isActive());
		assertTrue(tracker.getHeart().isReady());
		assertEquals(0, tracker.getHeart().getFinishedAgeSeconds(START), DELTA);
		tracker.tick(0, atTick(1));
		assertEquals(0.6, tracker.getHeart().getFinishedAgeSeconds(atTick(1)), DELTA);
	}

	@Test
	public void observedImbuedHeartUseStartsSevenMinuteSharedCooldown()
	{
		tracker.initialize(0, START);
		tracker.tick(70, atTick(1));

		assertTrue(tracker.getHeart().isKnown());
		assertEquals(420, tracker.getHeart().getRemainingSeconds(atTick(1)), DELTA);
		assertEquals(700, tracker.getHeart().getTotalTicks());
		assertEquals(1, tracker.getHeart().getRemainingFraction(atTick(1)), DELTA);
	}

	@Test
	public void observedSaturatedHeartUseStartsFiveMinuteSharedCooldown()
	{
		tracker.initialize(0, START);
		tracker.tick(50, atTick(1));

		assertEquals(300, tracker.getHeart().getRemainingSeconds(atTick(1)), DELTA);
		assertEquals(500, tracker.getHeart().getTotalTicks());
		assertEquals(1, tracker.getHeart().getRemainingFraction(atTick(1)), DELTA);
	}

	@Test
	public void unchangedHeartBucketCountsDownBetweenServerUpdates()
	{
		tracker.initialize(0, START);
		tracker.tick(50, atTick(1));
		for (int tick = 2; tick <= 10; tick++)
		{
			tracker.tick(50, atTick(tick));
		}

		assertEquals(294.6, tracker.getHeart().getRemainingSeconds(atTick(10)), DELTA);
		tracker.tick(49, atTick(11));
		assertEquals(294, tracker.getHeart().getRemainingSeconds(atTick(11)), DELTA);
	}

	@Test
	public void heartServerSampleCorrectsAnUnknownBucketPhase()
	{
		tracker.initialize(35, START);
		assertEquals(210, tracker.getHeart().getRemainingSeconds(START), DELTA);

		tracker.tick(34, atTick(1));
		assertEquals(204, tracker.getHeart().getRemainingSeconds(atTick(1)), DELTA);
	}

	@Test
	public void imbuedDurationIsPreservedWhenRemainingTimeDropsBelowFiveMinutes()
	{
		tracker.initialize(0, START);
		tracker.tick(70, atTick(1));
		tracker.tick(49, atTick(2));

		assertEquals(700, tracker.getHeart().getTotalTicks());
		assertEquals(0.7, tracker.getHeart().getRemainingFraction(atTick(2)), DELTA);
	}

	@Test
	public void increasingHeartSampleStartsNewSharedDuration()
	{
		tracker.initialize(20, START);
		tracker.tick(50, atTick(1));

		assertEquals(500, tracker.getHeart().getTotalTicks());
		assertEquals(300, tracker.getHeart().getRemainingSeconds(atTick(1)), DELTA);
	}

	@Test
	public void delayedHeartClearDoesNotDeclareReadyEarly()
	{
		tracker.initialize(1, START);
		for (int tick = 1; tick <= 25; tick++)
		{
			tracker.tick(1, atTick(tick));
		}

		assertTrue(tracker.getHeart().isActive());
		assertTrue(tracker.getHeart().getRemainingSeconds(atTick(26)) > 0);
		tracker.tick(0, atTick(26));
		assertFalse(tracker.getHeart().isActive());
	}

	@Test
	public void pausedHeartCannotCountDownBeyondItsAuthoritativeBucket()
	{
		tracker.initialize(30, START);
		for (int tick = 1; tick <= 100; tick++)
		{
			tracker.tick(30, atTick(tick));
		}

		assertEquals(174.6, tracker.getHeart().getRemainingSeconds(atTick(100)), DELTA);
		assertEquals(174, tracker.getHeart().getRemainingSeconds(atTick(101)), DELTA);
		assertEquals(-1, tracker.getHeart().getFinishedAgeSeconds(atTick(100)), DELTA);
	}

	@Test
	public void serverClearTriggersCompletionOnce()
	{
		tracker.initialize(1, START);
		tracker.tick(0, atTick(1));

		assertFalse(tracker.getHeart().isActive());
		assertEquals(0, tracker.getHeart().getFinishedAgeSeconds(atTick(1)), DELTA);
		tracker.tick(0, atTick(2));
		assertEquals(0.6, tracker.getHeart().getFinishedAgeSeconds(atTick(2)), DELTA);
	}

	@Test
	public void newHeartUseCancelsCompletionAnimation()
	{
		tracker.initialize(1, START);
		tracker.tick(0, atTick(1));
		tracker.tick(50, atTick(2));

		assertTrue(tracker.getHeart().isActive());
		assertEquals(-1, tracker.getHeart().getFinishedAgeSeconds(atTick(2)), DELTA);
	}

	@Test
	public void lifecycleResetWaitsForAConfirmedReadySample()
	{
		tracker.initialize(50, START);
		tracker.clear();

		assertFalse(tracker.getHeart().isActive());
		assertFalse(tracker.getHeart().isReady());
		assertEquals(-1, tracker.getHeart().getFinishedAgeSeconds(atTick(1)), DELTA);
		tracker.initialize(0, atTick(2));
		assertTrue(tracker.getHeart().isReady());
		assertEquals(0, tracker.getHeart().getFinishedAgeSeconds(atTick(2)), DELTA);
	}

	@Test
	public void reconnectDiscardsOldTimingAndRehydratesServerState()
	{
		tracker.initialize(0, START);
		tracker.tick(70, atTick(1));
		tracker.clear();
		assertFalse(tracker.getHeart().isActive());

		tracker.tick(10, atTick(100));
		assertEquals(60, tracker.getHeart().getRemainingSeconds(atTick(100)), DELTA);
		assertEquals(700, tracker.getHeart().getTotalTicks());
	}

	@Test
	public void negativeServerSamplesAreTreatedAsReady()
	{
		tracker.initialize(-1, START);
		assertFalse(tracker.getHeart().isActive());
		assertTrue(tracker.getHeart().isReady());
		assertEquals(0, tracker.getHeart().getFinishedAgeSeconds(START), DELTA);
		tracker.tick(50, atTick(1));
		tracker.tick(-1, atTick(2));

		assertFalse(tracker.getHeart().isActive());
		assertEquals(0, tracker.getHeart().getFinishedAgeSeconds(atTick(2)), DELTA);
	}

	private static long atTick(int tick)
	{
		return START + tick * Cooldown.TICK_NANOS;
	}
}

package com.cooldownoverlays;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.lang.reflect.Proxy;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.SpritePixels;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class InventoryCooldownOverlayTest
{
	private final CooldownTracker tracker = new CooldownTracker();
	private final PotionTimers potions = new PotionTimers();
	private final BoostPotionTimers boosts = new BoostPotionTimers();
	private GameState gameState = GameState.LOGGED_IN;
	private boolean enabled = true;
	private boolean itemsEnabled = true;
	private DisplayMode displayMode = DisplayMode.BOTH;
	private BorderStyle style = BorderStyle.ITEM_OUTLINE;
	private boolean spriteAvailable = true;
	private int spriteRequests;
	private int requestedId;
	private int requestedQuantity;
	private final Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
		new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			if (method.getName().equals("getGameState"))
			{
				return gameState;
			}
			if (method.getName().equals("createItemSprite"))
			{
				spriteRequests++;
				requestedId = (int) args[0];
				requestedQuantity = (int) args[1];
				return spriteAvailable ? sprite() : null;
			}
			throw new UnsupportedOperationException(method.getName());
		});
	private final CooldownOverlaysConfig config = new CooldownOverlaysConfig()
	{
		@Override public DisplayMode displayMode() { return displayMode; }
		@Override public boolean animateWhenReady() { return enabled; }
		@Override public AnimationMode animationMode() { return AnimationMode.PERMANENT; }
		@Override public BorderStyle animationBorderStyle() { return style; }
		@Override public boolean saturatedHeart() { return itemsEnabled; }
		@Override public boolean staminaPotion() { return itemsEnabled; }
		@Override public boolean superStrengthPotion() { return itemsEnabled; }
	};
	private final InventoryCooldownOverlay overlay = new InventoryCooldownOverlay(client, config,
		tracker, potions, boosts, new CooldownRenderer(config), new ItemOutlineCache(client));

	@Test
	public void readyHeartsEffectPotionsAndBoostPotionsUseTheirOwnSprite()
	{
		tracker.getHeart().setReady(0);
		potions.get(PotionEffect.STAMINA).setReady(0);
		boosts.get(BoostPotion.SUPER_STRENGTH).setReady(0);
		int[] items = {ItemID.SATURATED_HEART, ItemID._4DOSESTAMINA, ItemID._4DOSE2STRENGTH};
		for (int item : items)
		{
			assertTrue(visiblePixels(render(item, 2, null)) > 0);
			assertEquals(item, requestedId);
			assertEquals(2, requestedQuantity);
		}
		assertEquals(3, spriteRequests);
	}

	@Test
	public void inactiveHiddenOrRunningIconsDoNotRequestOutlineSprites()
	{
		render(ItemID.SATURATED_HEART, 1, null);
		tracker.getHeart().start(100, 100, System.nanoTime());
		render(ItemID.SATURATED_HEART, 1, null);
		tracker.getHeart().setReady(0);
		enabled = false;
		assertEquals(0, visiblePixels(render(ItemID.SATURATED_HEART, 1, null)));
		enabled = true;
		gameState = GameState.LOGIN_SCREEN;
		assertEquals(0, visiblePixels(render(ItemID.SATURATED_HEART, 1, null)));
		assertEquals(0, spriteRequests);
	}

	@Test
	public void slotStyleDrawsWithoutRequestingASpriteAndMissingOutlineHasNoFallback()
	{
		tracker.getHeart().setReady(0);
		style = BorderStyle.INVENTORY_SLOT;
		assertTrue(visiblePixels(render(ItemID.SATURATED_HEART, 1, null)) > 0);
		assertEquals(0, spriteRequests);
		style = BorderStyle.ITEM_OUTLINE;
		spriteAvailable = false;
		assertEquals(0, visiblePixels(render(ItemID.SATURATED_HEART, 1, null)));
		assertEquals(1, spriteRequests);
		spriteAvailable = true;
		assertTrue(visiblePixels(render(ItemID.SATURATED_HEART, 1, null)) > 0);
		assertEquals(2, spriteRequests);
	}

	@Test
	public void outlineFollowsTheDraggedItemInsteadOfTheOriginalSlot()
	{
		tracker.getHeart().setReady(0);
		BufferedImage image = render(ItemID.SATURATED_HEART, 1, new Rectangle(48, 40, 36, 32));
		assertTrue(visiblePixels(image) > 0);
		for (int x = 0; x < 45; x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				assertEquals("The original slot must not glow during a drag", 0, image.getRGB(x, y));
			}
		}
	}

	@Test
	public void bothItemFillModesUseTheActiveItemSpriteWithoutReadyAnimations()
	{
		startActiveCooldowns();
		enabled = false;
		style = BorderStyle.INVENTORY_SLOT;
		displayMode = DisplayMode.ITEM_FILL;
		int[] items = {ItemID.SATURATED_HEART, ItemID._4DOSESTAMINA, ItemID._4DOSE2STRENGTH};
		for (int item : items)
		{
			assertTrue(visiblePixels(render(item, 2, null)) > 0);
			assertEquals(item, requestedId);
			assertEquals(2, requestedQuantity);
		}
		assertEquals(3, spriteRequests);

		displayMode = DisplayMode.TIMER_AND_ITEM_FILL;
		for (int item : items)
		{
			assertTrue(visiblePixels(render(item, 2, null)) > 0);
		}
		assertEquals("Switching fill modes must reuse the same item silhouettes", 3, spriteRequests);
	}

	@Test
	public void activeItemFillCachesSilhouettesByItemAndQuantityAcrossFrames()
	{
		startActiveCooldowns();
		displayMode = DisplayMode.ITEM_FILL;
		render(ItemID.SATURATED_HEART, 1, null);
		render(ItemID.SATURATED_HEART, 1, null);
		assertEquals(1, spriteRequests);
		render(ItemID.SATURATED_HEART, 3, null);
		assertEquals(2, spriteRequests);
		assertEquals(ItemID.SATURATED_HEART, requestedId);
		assertEquals(3, requestedQuantity);
		render(ItemID.SATURATED_HEART, 3, null);
		assertEquals(2, spriteRequests);
	}

	@Test
	public void activeItemFillFollowsTheDraggedItem()
	{
		startActiveCooldowns();
		displayMode = DisplayMode.ITEM_FILL;
		BufferedImage image = render(ItemID.SATURATED_HEART, 1, new Rectangle(48, 40, 36, 32));
		assertTrue(visiblePixels(image) > 0);
		for (int x = 0; x < 45; x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				assertEquals("The cooldown mask must follow the dragged icon", 0, image.getRGB(x, y));
			}
		}
	}

	@Test
	public void disabledLoggedOutAndUnrelatedItemsDoNotRequestFillSprites()
	{
		startActiveCooldowns();
		displayMode = DisplayMode.ITEM_FILL;
		int[] items = {ItemID.SATURATED_HEART, ItemID._4DOSESTAMINA, ItemID._4DOSE2STRENGTH};
		itemsEnabled = false;
		for (int item : items)
		{
			assertEquals(0, visiblePixels(render(item, 1, null)));
		}
		itemsEnabled = true;
		gameState = GameState.LOGIN_SCREEN;
		for (int item : items)
		{
			assertEquals(0, visiblePixels(render(item, 1, null)));
		}
		gameState = GameState.LOGGED_IN;
		assertEquals(0, visiblePixels(render(ItemID.COINS, 1, null)));
		assertEquals(0, spriteRequests);
	}

	@Test
	public void missingActiveFillSpriteRetriesWithoutDrawingAnInventoryTile()
	{
		startActiveCooldowns();
		displayMode = DisplayMode.ITEM_FILL;
		spriteAvailable = false;
		assertEquals(0, visiblePixels(render(ItemID.SATURATED_HEART, 1, null)));
		assertEquals(1, spriteRequests);
		spriteAvailable = true;
		BufferedImage image = render(ItemID.SATURATED_HEART, 1, null);
		assertTrue(visiblePixels(image) > 0);
		assertEquals(2, spriteRequests);
		assertEquals("The inventory tile outside the item silhouette must stay clear", 0, image.getRGB(9, 9));
	}

	private void startActiveCooldowns()
	{
		long nowNanos = System.nanoTime();
		tracker.getHeart().start(100, 200, nowNanos);
		potions.get(PotionEffect.STAMINA).start(100, 200, nowNanos);
		boosts.get(BoostPotion.SUPER_STRENGTH).start(100, 200, nowNanos);
	}

	private BufferedImage render(int item, int quantity, Rectangle dragging)
	{
		BufferedImage image = new BufferedImage(96, 80, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			overlay.renderItemOverlay(graphics, item,
				new WidgetItem(item, quantity, new Rectangle(8, 8, 36, 32), null, dragging));
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}

	private static SpritePixels sprite()
	{
		BufferedImage image = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setColor(Color.WHITE);
		graphics.fillRect(10, 6, 16, 20);
		graphics.dispose();
		return (SpritePixels) Proxy.newProxyInstance(SpritePixels.class.getClassLoader(),
			new Class<?>[]{SpritePixels.class}, (proxy, method, args) ->
			{
				if (method.getName().equals("toBufferedImage") && method.getParameterCount() == 0)
				{
					return image;
				}
				throw new UnsupportedOperationException(method.getName());
			});
	}

	private static int visiblePixels(BufferedImage image)
	{
		int count = 0;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) != 0)
				{
					count++;
				}
			}
		}
		return count;
	}
}

package com.cooldownoverlays;

import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.lang.reflect.Proxy;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.SpritePixels;
import net.runelite.api.widgets.ItemQuantityMode;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class ItemOutlineCacheTest
{
	private BufferedImage image = visibleSprite();
	private int requests;
	private Object[] lastArguments;
	private final Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
		new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			if (!method.getName().equals("createItemSprite"))
			{
				throw new UnsupportedOperationException(method.getName());
			}
			requests++;
			lastArguments = args.clone();
			return image == null ? null : sprite(image);
		});
	private final ItemOutlineCache cache = new ItemOutlineCache(client);

	@Test
	public void tracesTheActualIrregularSilhouetteAndDisconnectedPixels()
	{
		BufferedImage sprite = blankSprite();
		sprite.setRGB(2, 2, 0xffffffff);
		sprite.setRGB(3, 2, 0xffffffff);
		sprite.setRGB(2, 3, 0xffffffff);
		sprite.setRGB(7, 6, 0xffffffff);
		Shape outline = ItemOutlineCache.trace(sprite);

		assertTrue(outline.contains(2.5, 2.5));
		assertTrue(outline.contains(3.5, 2.5));
		assertTrue(outline.contains(2.5, 3.5));
		assertTrue(outline.contains(7.5, 6.5));
		assertFalse(outline.contains(3.5, 3.5));
		assertFalse(outline.contains(5.5, 4.5));
		assertEquals(new Rectangle(2, 2, 6, 5), outline.getBounds());
	}

	@Test
	public void retainsTransparentHolesInsteadOfFillingTheBoundingBox()
	{
		BufferedImage sprite = blankSprite();
		for (int y = 1; y <= 5; y++)
		{
			for (int x = 1; x <= 5; x++)
			{
				if (x == 1 || x == 5 || y == 1 || y == 5)
				{
					sprite.setRGB(x, y, 0xffffffff);
				}
			}
		}
		Shape outline = ItemOutlineCache.trace(sprite);

		assertTrue(outline.contains(1.5, 3.5));
		assertTrue(outline.contains(5.5, 3.5));
		assertFalse(outline.contains(3.5, 3.5));
		assertFalse(outline.contains(0.5, 3.5));
	}

	@Test
	public void alphaDefinesVisibilityIncludingBlackAndPartiallyTransparentPixels()
	{
		BufferedImage sprite = blankSprite();
		sprite.setRGB(1, 1, 0xff000000);
		sprite.setRGB(2, 1, 0x01ffffff);
		sprite.setRGB(3, 1, 0x00ffffff);
		Shape outline = ItemOutlineCache.trace(sprite);

		assertTrue(outline.contains(1.5, 1.5));
		assertTrue(outline.contains(2.5, 1.5));
		assertFalse(outline.contains(3.5, 1.5));
		assertNull(ItemOutlineCache.trace(blankSprite()));
		assertNull(ItemOutlineCache.trace(null));
	}

	@Test
	public void requestsRawNativeSpriteWithoutCountBorderOrShadow()
	{
		cache.getOutline(123, 17);

		assertArrayEquals(new Object[]{123, 17, 0, 0, ItemQuantityMode.NEVER, false,
			Constants.CLIENT_DEFAULT_ZOOM}, lastArguments);
	}

	@Test
	public void cachesEachExactItemAndQuantityPair()
	{
		Shape first = cache.getOutline(10, 1);
		assertSame(first, cache.getOutline(10, 1));
		assertEquals(1, requests);
		assertNotSame(first, cache.getOutline(11, 1));
		assertNotSame(first, cache.getOutline(10, 2));
		Shape negativeQuantity = cache.getOutline(10, -1);
		assertNotSame(negativeQuantity, cache.getOutline(11, -1));
		assertSame(negativeQuantity, cache.getOutline(10, -1));
		assertEquals(5, requests);
	}

	@Test
	public void missingSpritesAreRetriedUntilAvailable()
	{
		image = null;
		assertNull(cache.getOutline(10, 1));
		assertNull(cache.getOutline(10, 1));
		image = visibleSprite();
		Shape loaded = cache.getOutline(10, 1);

		assertTrue(loaded.contains(2.5, 2.5));
		assertSame(loaded, cache.getOutline(10, 1));
		assertEquals(3, requests);
	}

	@Test
	public void blankSpritesAreRetriedInsteadOfCachingAnEmptyContour()
	{
		image = blankSprite();
		assertNull(cache.getOutline(10, 1));
		assertNull(cache.getOutline(10, 1));
		image.setRGB(4, 5, 0xffffffff);
		Shape loaded = cache.getOutline(10, 1);

		assertTrue(loaded.contains(4.5, 5.5));
		assertSame(loaded, cache.getOutline(10, 1));
		assertEquals(3, requests);
	}

	@Test
	public void boundedCacheEvictsTheLeastRecentlyUsedShape()
	{
		for (int item = 0; item < 128; item++)
		{
			cache.getOutline(item, 1);
		}
		Shape retained = cache.getOutline(0, 1);
		cache.getOutline(128, 1);
		assertSame(retained, cache.getOutline(0, 1));
		assertEquals(129, requests);
		cache.getOutline(1, 1);
		assertEquals(130, requests);
	}

	@Test
	public void clearDiscardsCachedGeometry()
	{
		Shape first = cache.getOutline(10, 1);
		cache.clear();
		assertNotSame(first, cache.getOutline(10, 1));
		assertEquals(2, requests);
	}

	private static BufferedImage blankSprite()
	{
		return new BufferedImage(10, 8, BufferedImage.TYPE_INT_ARGB);
	}

	private static BufferedImage visibleSprite()
	{
		BufferedImage sprite = blankSprite();
		sprite.setRGB(2, 2, 0xffffffff);
		return sprite;
	}

	private static SpritePixels sprite(BufferedImage image)
	{
		return (SpritePixels) Proxy.newProxyInstance(SpritePixels.class.getClassLoader(),
			new Class<?>[]{SpritePixels.class}, (proxy, method, args) ->
			{
				if (method.getName().equals("toBufferedImage") && method.getParameterCount() == 0)
				{
					return image;
				}
				throw new UnsupportedOperationException(method.getName());
			});
	}
}

package com.cooldownoverlays;

import java.awt.Frame;
import org.junit.Assume;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class MacOSRuntimeAccessTest
{
	@Test
	public void macOsDesktopPackagesAreAccessibleToRuneLite() throws ClassNotFoundException
	{
		Assume.assumeTrue(System.getProperty("os.name").startsWith("Mac"));

		Module desktopModule = Frame.class.getModule();
		Module pluginModule = MacOSRuntimeAccessTest.class.getModule();
		assertTrue("macOS desktop integration must be exported to RuneLite",
			desktopModule.isExported("com.apple.eawt", pluginModule));
		assertTrue("macOS fullscreen events must be exported to RuneLite",
			desktopModule.isExported("com.apple.eawt.event", pluginModule));
		// Link the package-private adapter without creating a window or starting RuneLite.
		// Keep this test outside RuneLite's signed packages to avoid signer conflicts.
		assertNotNull(Class.forName("net.runelite.client.ui.OSXFullScreenAdapter", false,
			MacOSRuntimeAccessTest.class.getClassLoader()));
	}
}

